    run.iterations.forEach(it => {
      const v = it.phases[p]; if (v == null || v <= 0) return;
      const c = el("circle", {class: "dot", cx: x(v), cy: y, r: 5, fill: COLORS[Math.min(run.timeline.indexOf(p) < 0 ? 7 : run.timeline.indexOf(p), 7)], "fill-opacity": .55, stroke: "var(--card)", "stroke-width": 1, tabindex: 0}, svg);
