     it.stale_end || "", it.foreign || "", it.final_location, it.op_error || it.execute_error || ""].forEach((v, k) => { const td = h("td", k === 0 && bad ? "flag" : null, String(v ?? "–")); r.append(td); });
    t.append(r); });
