-- UI RUNOPTS
 * "select"|"bool"|"number", choices: [...], default, min, max, step, hint}].
 * Rendered generically so the UI stays shared. */
function renderRunOptions(options) {
  const box = $("run-options");
  box.innerHTML = "";
  box.hidden = !options.length;
  for (const option of options) {
    const label = document.createElement("label");
    if (option.type === "bool") {
      label.className = "check";
      const input = document.createElement("input");
      input.type = "checkbox";
      input.dataset.option = option.name;
      input.checked = Boolean(option.default);
      label.append(input, document.createTextNode(" " + (option.label || option.name)));
    } else if (option.type === "number") {
      label.append(document.createTextNode(option.label || option.name));
      const input = document.createElement("input");
      input.type = "number";
      input.dataset.option = option.name;
      for (const attribute of ["min", "max", "step"]) {
        if (option[attribute] !== undefined && option[attribute] !== null) {
          input[attribute] = option[attribute];
        }
      }
      input.value = option.default ?? "";
      if (option.hint) input.title = option.hint;
      label.append(input);
    } else {
      label.append(document.createTextNode(option.label || option.name));
      const select = document.createElement("select");
      select.dataset.option = option.name;
      for (const choice of option.choices || []) {
        const el = document.createElement("option");
        el.value = choice;
        el.textContent = choice;
        if (choice === option.default) el.selected = true;
        select.append(el);
      }
      label.append(select);
    }
    box.append(label);
  }
}

