//! audi-arg3-rust — the ARG3 move-up longterm test, in Rust.
//!
//! Third variant of the same app: `../sdk` uses the NOVA Python SDK, `../api`
//! uses the generated Python API client with minimal overhead, this one uses
//! the Rust client (vendored under `vendor/`). Same motions, same IO gating,
//! same operational semantics — but the motion group state streams run at the
//! controller's step rate, which the Python apps could not afford.

mod busio;
mod config;
mod discovery;
mod execution_fsm;
mod iocreate;
mod logsfs;
mod motion;
mod nova;
mod robot;
mod robotlog;
mod runner;
mod web;

use std::sync::Arc;

use tokio_util::sync::CancellationToken;

fn init_tracing() {
    // LOG_LEVEL (info/debug/warn/error) for parity with the Python apps;
    // RUST_LOG still wins when set.
    let default = std::env::var("LOG_LEVEL").unwrap_or_else(|_| "info".to_string());
    let filter = tracing_subscriber::EnvFilter::try_from_default_env()
        .unwrap_or_else(|_| tracing_subscriber::EnvFilter::new(default));
    tracing_subscriber::fmt().with_env_filter(filter).init();
}

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    init_tracing();
    let cfg = config::Config::from_env();
    tracing::info!(
        nova_api = %cfg.nova_api,
        cell = %cfg.cell,
        base_path = %cfg.base_path,
        log_dir = %cfg.log_dir,
        "starting audi-arg3-rust"
    );

    let nova = nova::Nova::connect(&cfg)?;
    let shutdown = CancellationToken::new();

    let hub = busio::IoHub::new(&cfg.cell, cfg.nats_url());
    let hub_task = tokio::spawn(hub.clone().run(shutdown.child_token()));

    // Robot status snapshots also go out on NATS (parity with the api variant,
    // for a unified frontend); its own connection, fire-and-forget.
    let (publisher, status_rx) =
        busio::StatusPublisher::new(cfg.status_subject.clone(), cfg.nats_url());
    let publisher_task = tokio::spawn(publisher.clone().run(status_rx, shutdown.child_token()));

    let runner = runner::Runner::new(
        nova.clone(),
        cfg.clone(),
        hub.clone(),
        Some(publisher.clone()),
        shutdown.clone(),
    );

    let state = web::AppState {
        cfg: Arc::new(cfg.clone()),
        nova,
        hub,
        runner: runner.clone(),
        publisher,
    };
    let app = web::router(state);

    let listener = tokio::net::TcpListener::bind(("0.0.0.0", cfg.port)).await?;
    tracing::info!(port = cfg.port, "listening");

    let server_shutdown = shutdown.clone();
    let server = axum::serve(listener, app).with_graceful_shutdown(async move {
        server_shutdown.cancelled().await;
    });

    tokio::spawn(async move {
        let ctrl_c = tokio::signal::ctrl_c();
        #[cfg(unix)]
        {
            let mut sigterm =
                tokio::signal::unix::signal(tokio::signal::unix::SignalKind::terminate())
                    .expect("installing SIGTERM handler");
            tokio::select! {
                _ = ctrl_c => {}
                _ = sigterm.recv() => {}
            }
        }
        #[cfg(not(unix))]
        {
            let _ = ctrl_c.await;
        }
        tracing::info!("shutdown signal received");
        shutdown.cancel();
    });

    server.await?;

    // Robots observe the cancellation at their next await point; bound the
    // wait so an open websocket cannot hold shutdown hostage.
    if tokio::time::timeout(std::time::Duration::from_secs(5), runner.shutdown())
        .await
        .is_err()
    {
        tracing::warn!("robot tasks did not finish within 5s, exiting anyway");
    }
    hub_task.abort();
    publisher_task.abort();
    Ok(())
}
//! Configuration. Same variables and defaults as the Python api app
//! (audi_arg3_api/config.py), so the two are interchangeable in a manifest.

use std::time::Duration;

fn env(name: &str) -> Option<String> {
    std::env::var(name)
        .ok()
        .map(|v| v.trim().to_string())
        .filter(|v| !v.is_empty())
}

fn env_or(name: &str, default: &str) -> String {
    env(name).unwrap_or_else(|| default.to_string())
}

fn env_parse<T: std::str::FromStr>(name: &str, default: T) -> T {
    env(name).and_then(|v| v.parse().ok()).unwrap_or(default)
}

/// The app-operator injects NOVA_API **without** a scheme in-cluster
/// (e.g. `api-gateway:8080`). Used as-is, url parsing reads `api-gateway` as
/// the scheme and the NATS derivation loses the hostname. Same fix as the
/// Python api app's `with_scheme()`.
pub fn with_scheme(host: &str) -> String {
    let host = host.trim().trim_end_matches('/');
    if host.starts_with("http://") || host.starts_with("https://") {
        host.to_string()
    } else {
        format!("http://{host}")
    }
}

#[derive(Debug, Clone)]
pub struct Config {
    /// NOVA instance, scheme-normalized (e.g. `http://172.31.13.10`).
    pub nova_api: String,
    pub access_token: Option<String>,
    pub cell: String,
    /// Ingress prefix the operator injects (`/cell/<app>`); empty locally.
    pub base_path: String,
    pub port: u16,
    pub log_dir: String,
    pub log_max_bytes: u64,
    pub log_backup_count: u32,
    /// Active TCP the programs run against ("1" on the physical cell,
    /// "Flange" on stock virtual robots).
    pub tcp: String,
    /// Motion-group state stream rate in ms. 0 = ask NOVA for the controller's
    /// step rate (cycle_time from the motion group description). The Python
    /// api app throttled to 200 ms because pydantic could not keep up with
    /// step-rate frames; this app is built to consume them.
    pub state_response_rate_ms: i32,
    pub motion_timeout: Duration,
    pub wait_io: String,
    pub stop_io: String,
    /// NATS subject the robot status snapshots are published on
    /// (`STATUS_SUBJECT`, default `audi-arg3.rust.{cell}.status`). App-scoped
    /// so the api variant on the same cell has its own; set it explicitly if a
    /// cluster's NATS ACL only allows subjects under `nova.v2.cells.{cell}.*`.
    pub status_subject: String,
}

pub const DEFAULT_Z_OFFSET_MM: f64 = 100.0;
pub const DEFAULT_VELOCITY: f64 = 50.0; // mm/s TCP
pub const DEFAULT_ACCELERATION: f64 = 250.0;
pub const DEFAULT_TCP_JERK: f64 = 2500.0;
pub const DEFAULT_AXIS_TRAVEL_MM: f64 = 100.0;
pub const DEFAULT_AXIS_VELOCITY: f64 = 200.0; // mm/s prismatic joint
pub const AXIS_TCP: &str = "0";

impl Config {
    pub fn from_env() -> Self {
        let cell = env_or("CELL_NAME", "cell");
        Self {
            nova_api: with_scheme(&env_or("NOVA_API", "http://localhost")),
            access_token: env("NOVA_ACCESS_TOKEN"),
            status_subject: env("STATUS_SUBJECT")
                .unwrap_or_else(|| format!("audi-arg3.rust.{cell}.status")),
            cell,
            base_path: {
                let bp = env_or("BASE_PATH", "");
                let bp = bp.trim_end_matches('/');
                if bp.is_empty() || bp.starts_with('/') {
                    bp.to_string()
                } else {
                    format!("/{bp}")
                }
            },
            port: env_parse("PORT", 3000),
            log_dir: env_or("LOG_DIR", "./logs"),
            log_max_bytes: env_parse("LOG_MAX_BYTES", 10_000_000),
            log_backup_count: env_parse("LOG_BACKUP_COUNT", 1),
            tcp: env_or("TCP", "1"),
            state_response_rate_ms: env_parse("STATE_RESPONSE_RATE_MS", 0),
            motion_timeout: Duration::from_secs_f64(env_parse("MOTION_TIMEOUT_S", 300.0)),
            wait_io: env_or("WAIT_IO", "start"),
            stop_io: env_or("STOP_IO", "stop"),
        }
    }

    /// NATS endpoint. `NATS_BROKER` wins when set — in-cluster the operator
    /// injects `REDACTED` (plain TCP; the internal
    /// gateway does not proxy `/api/nats`). Otherwise derived from NOVA_API
    /// like the Python api app: `ws[s]://{host}[:port]/api/nats`. A default
    /// port is NOT spelled out — an explicit `:80` ends up in the websocket
    /// Host header and the NOVA ingress answers 502 to that (observed live).
    pub fn nats_url(&self) -> String {
        if let Some(broker) = env("NATS_BROKER") {
            return broker;
        }
        let (scheme, rest) = if let Some(r) = self.nova_api.strip_prefix("https://") {
            ("wss", r)
        } else {
            (
                "ws",
                self.nova_api
                    .strip_prefix("http://")
                    .unwrap_or(&self.nova_api),
            )
        };
        format!("{scheme}://{rest}/api/nats")
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn with_scheme_normalizes_operator_injected_hosts() {
        assert_eq!(with_scheme("api-gateway:8080"), "http://api-gateway:8080");
        assert_eq!(with_scheme("http://10.0.0.1/"), "http://10.0.0.1");
        assert_eq!(
            with_scheme("https://x.wandelbots.io"),
            "https://x.wandelbots.io"
        );
    }

    #[test]
    fn nats_url_keeps_path_and_omits_default_port() {
        let mut cfg = Config::from_env();
        cfg.nova_api = "http://172.31.13.10".into();
        // No explicit :80 — the ingress 502s on a Host header with it.
        assert_eq!(cfg.nats_url(), "ws://172.31.13.10/api/nats");
        cfg.nova_api = "http://api-gateway:8080".into();
        assert_eq!(cfg.nats_url(), "ws://api-gateway:8080/api/nats");
        cfg.nova_api = "https://foo.instance.wandelbots.io".into();
        assert_eq!(cfg.nats_url(), "wss://foo.instance.wandelbots.io/api/nats");
    }
}
//! Client construction. The facade (`NovaClient`) provides the two hand-written
//! websockets (state stream, trajectory execution); everything else this app
//! needs (planning, modes, descriptions, bus IOs) only exists on the generated
//! `raw` client. There is no bridge between the two, so both are built on one
//! shared reqwest client carrying the bearer token as a default header.

use nova_client::NovaClient;

use crate::config::Config;

#[derive(Clone)]
pub struct Nova {
    pub client: NovaClient,
    pub raw: nova_client::raw::Client,
    pub cell: String,
}

impl Nova {
    pub fn connect(cfg: &Config) -> Result<Self, nova_client::Error> {
        let mut headers = reqwest::header::HeaderMap::new();
        if let Some(token) = &cfg.access_token {
            let mut value = reqwest::header::HeaderValue::from_str(&format!("Bearer {token}"))
                .map_err(|e| nova_client::Error::InvalidRequest(format!("access token: {e}")))?;
            value.set_sensitive(true);
            headers.insert(reqwest::header::AUTHORIZATION, value);
        }
        let http = reqwest::Client::builder()
            .default_headers(headers)
            .connect_timeout(std::time::Duration::from_secs(10))
            // Planning calls with long trajectories can exceed the client's
            // 30 s default.
            .timeout(std::time::Duration::from_secs(120))
            .build()
            .map_err(|e| nova_client::Error::InvalidRequest(format!("http client: {e}")))?;

        let mut builder = NovaClient::builder(&cfg.nova_api)
            .default_cell(&cfg.cell)
            .http_client(http.clone());
        if let Some(token) = &cfg.access_token {
            builder = builder.bearer_token(token);
        }
        let client = builder.build()?;
        let raw = nova_client::raw::Client::new_with_client(client.base_url().as_str(), http);
        Ok(Self {
            client,
            raw,
            cell: cfg.cell.clone(),
        })
    }
}

//! Plan and execute the move-up motion. A direct port of the Python api app's
//! `motion.py` — see `../api/audi_arg3_api/motion.py` and
//! `../api/docs/execution-completion-detection.md` for the reasoning.
//!
//! The three things the SDK hides, spelled out:
//!
//! 1. **Planning** is one `plan_trajectory` call built from the motion group
//!    description (limits, mounting, TCP offset, payload) plus the current
//!    joint position.
//! 2. **Execution** is a websocket that only ever answers with
//!    acknowledgements. It never says "the motion finished".
//! 3. **Completion** is observed from the motion group state stream. This app
//!    streams at the controller's step rate (the terminal `TrajectoryEnded`
//!    frame exists for exactly one 4 ms step); the "execute block cleared at
//!    standstill after movement" fallback stays in place for when that frame
//!    is still lost.

use std::time::{Duration, Instant};

use anyhow::{anyhow, bail, Context, Result};
use futures_util::StreamExt;
use nova_client::types as t;
use tokio_util::sync::CancellationToken;

use crate::config::{
    Config, AXIS_TCP, DEFAULT_ACCELERATION, DEFAULT_AXIS_TRAVEL_MM, DEFAULT_AXIS_VELOCITY,
    DEFAULT_TCP_JERK, DEFAULT_VELOCITY, DEFAULT_Z_OFFSET_MM,
};
use crate::nova::Nova;
use crate::robotlog::RobotLog;

/// A planned trajectory plus the stream rate to observe its execution with.
pub struct Planned {
    pub trajectory: t::JointTrajectory,
    /// What goes on the wire as the state stream's `response_rate`: `None`
    /// asks the server for the controller's own step rate (the same request
    /// the SDK variant makes), `Some(ms)` throttles.
    pub response_rate: Option<i32>,
    /// The controller's step rate (cycle_time) for the log line and the UI --
    /// never sent, so a step-rate run is byte-identical across the variants.
    pub step_rate_ms: i32,
    /// The TCP the trajectory was planned for; execution passes it in
    /// `TrajectoryData.tcp` so the controller uses the same tool.
    pub tcp: String,
}

/// Pick the payload the planner should use, mirroring the SDK's precedence.
///
/// **This is not cosmetic.** The planner uses the payload for dynamics.
/// Planning with no payload sizes the trajectory for an unloaded robot, and
/// executing that with a real tool on the flange makes the controller exceed
/// its motor torque ("Sollmotormoment"). Tools on this cell are 68.6–160.1 kg.
///
/// Precedence: payload named like the TCP → active payload → the only
/// registered payload → none.
pub fn resolve_payload<'a>(
    description: &'a t::MotionGroupDescription,
    tcp: &str,
    active_payload: Option<&str>,
) -> Option<&'a t::Payload> {
    let payloads = &description.payloads;
    if let Some(p) = payloads.get(tcp) {
        return Some(p);
    }
    if let Some(active) = active_payload {
        if let Some(p) = payloads.get(active) {
            return Some(p);
        }
    }
    if payloads.len() == 1 {
        return payloads.values().next();
    }
    None
}

async fn get_description(
    nova: &Nova,
    controller: &str,
    motion_group: &str,
) -> Result<t::MotionGroupDescription> {
    Ok(nova
        .raw
        .get_motion_group_description()
        .cell(&nova.cell)
        .controller(controller)
        .motion_group(motion_group)
        .send()
        .await
        .with_context(|| format!("{motion_group}: get_motion_group_description"))?
        .into_inner())
}

pub async fn current_state(
    nova: &Nova,
    controller: &str,
    motion_group: &str,
) -> Result<t::MotionGroupState> {
    Ok(nova
        .raw
        .get_current_motion_group_state()
        .cell(&nova.cell)
        .controller(controller)
        .motion_group(motion_group)
        .send()
        .await
        .with_context(|| format!("{motion_group}: get_current_motion_group_state"))?
        .into_inner())
}

/// Assemble the planner setup from the motion group description.
///
/// `global_limits` is the controller maximum (auto-mode limits); the per-motion
/// user limits ride as a `limits_override` on each command, like the SDK does.
fn build_setup(
    description: &t::MotionGroupDescription,
    tcp: &str,
    state: &t::MotionGroupState,
    log: &RobotLog,
) -> t::MotionGroupSetup {
    let motion_group = &state.motion_group;
    let tcp_offset = description.tcps.get(tcp).map(|o| o.pose.clone());

    let payload = resolve_payload(description, tcp, state.payload.as_deref());
    match payload {
        None => log.warn(&format!(
            "{motion_group}: no payload resolved for TCP '{tcp}' (registered: {:?}) -- planning \
             as an UNLOADED robot. If a tool is mounted the controller can exceed its motor \
             torque during execution.",
            description.payloads.keys().collect::<Vec<_>>()
        )),
        Some(p) => log.info(&format!(
            "{motion_group}: planning with payload '{}' ({} kg, com={:?})",
            p.name, p.payload, p.center_of_mass
        )),
    }

    t::MotionGroupSetup {
        collision_setups: None,
        cycle_time: description.cycle_time.unwrap_or(8),
        global_limits: description.operation_limits.auto_limits.clone(),
        motion_group_model: description.motion_group_model.clone(),
        mounting: description.mounting.clone(),
        payload: payload.cloned(),
        tcp_offset,
    }
}

/// The per-segment motion limits, identical to the SDK app's MotionSettings.
fn limits() -> t::LimitsOverride {
    t::LimitsOverride {
        tcp_velocity_limit: Some(DEFAULT_VELOCITY),
        tcp_acceleration_limit: Some(DEFAULT_ACCELERATION),
        tcp_jerk_limit: Some(DEFAULT_TCP_JERK),
        joint_acceleration_limits: vec![],
        joint_jerk_limits: vec![],
        joint_velocity_limits: vec![],
        tcp_orientation_acceleration_limit: None,
        tcp_orientation_jerk_limit: None,
        tcp_orientation_velocity_limit: None,
    }
}

fn ptp(target: t::Pose) -> t::MotionCommand {
    t::MotionCommand {
        blending: None,
        limits_override: Some(limits()),
        path: t::MotionCommandPath::CartesianPtp(t::PathCartesianPtp {
            kinematic_configuration: None,
            path_definition_name: t::PathCartesianPtpPathDefinitionName::PathCartesianPtp,
            target_pose: target,
        }),
    }
}

fn joint_ptp(target: f64) -> t::MotionCommand {
    t::MotionCommand {
        blending: None,
        limits_override: Some(t::LimitsOverride {
            joint_velocity_limits: vec![DEFAULT_AXIS_VELOCITY],
            joint_acceleration_limits: vec![DEFAULT_ACCELERATION],
            joint_jerk_limits: vec![DEFAULT_TCP_JERK],
            tcp_velocity_limit: None,
            tcp_acceleration_limit: None,
            tcp_jerk_limit: None,
            tcp_orientation_acceleration_limit: None,
            tcp_orientation_jerk_limit: None,
            tcp_orientation_velocity_limit: None,
        }),
        path: t::MotionCommandPath::JointPtp(t::PathJointPtp {
            path_definition_name: t::PathJointPtpPathDefinitionName::PathJointPtp,
            target_joint_position: t::DoubleArray(vec![target]),
        }),
    }
}

/// Build the two-segment "move up, then back home" motion: raise the TCP by
/// `z_offset_mm` in Z, keeping the orientation, then return to the start.
fn up_and_back_commands(home: &t::Pose, z_offset_mm: f64) -> Result<Vec<t::MotionCommand>> {
    let position = home
        .position
        .as_ref()
        .ok_or_else(|| anyhow!("current TCP pose has no position, cannot plan"))?;
    let orientation = home
        .orientation
        .as_ref()
        .ok_or_else(|| anyhow!("current TCP pose has no orientation, cannot plan"))?;

    let [x, y, z] = position.0;
    let up = t::Pose {
        position: Some(t::Vector3d([x, y, z + z_offset_mm])),
        orientation: Some(orientation.clone()),
    };
    Ok(vec![ptp(up), ptp(home.clone())])
}

/// Return the (lower, upper) position limits of a single-joint axis.
fn axis_limits(setup: &t::MotionGroupSetup) -> Result<(f64, f64)> {
    let missing = || anyhow!("linear axis has no position limits configured");
    let position = setup
        .global_limits
        .as_ref()
        .and_then(|l| l.joints.first())
        .and_then(|j| j.position.as_ref())
        .ok_or_else(missing)?;
    match (position.lower_limit, position.upper_limit) {
        (Some(lower), Some(upper)) => Ok((lower, upper)),
        _ => Err(missing()),
    }
}

/// Pick the axis target, moving toward whichever end is farther away, clamped
/// to stay inside the axis range. Same rule as both Python apps.
pub fn compute_axis_target(current: f64, travel_mm: f64, lower: f64, upper: f64) -> f64 {
    if (upper - current).abs() >= (current - lower).abs() {
        (current + travel_mm).min(upper)
    } else {
        (current - travel_mm).max(lower)
    }
}

async fn plan(
    nova: &Nova,
    motion_group: &str,
    setup: t::MotionGroupSetup,
    start: &t::Joints,
    commands: Vec<t::MotionCommand>,
) -> Result<t::JointTrajectory> {
    let response = nova
        .raw
        .plan_trajectory()
        .cell(&nova.cell)
        .body(t::PlanTrajectoryRequest {
            motion_commands: commands,
            motion_group_setup: setup,
            singularity_handling: None,
            start_joint_position: t::DoubleArray(start.0.clone()),
        })
        .send()
        .await
        .with_context(|| format!("{motion_group}: plan_trajectory"))?
        .into_inner();

    match response.response {
        t::PlanTrajectoryResponseResponse::JointTrajectory(trajectory) => Ok(trajectory),
        t::PlanTrajectoryResponseResponse::PlanTrajectoryFailedResponse(failed) => Err(anyhow!(
            "{motion_group}: planning failed at location {:?}: {:?}",
            failed.error_location_on_trajectory.0,
            failed.error_feedback
        )),
    }
}

/// The controller's own step rate: the recommended stream rate, and the only
/// one at which the single-step terminal frame is reliably visible.
fn step_rate(description: &t::MotionGroupDescription) -> i32 {
    description.cycle_time.unwrap_or(8)
}

/// The `response_rate` to request. 0 (the default) means "the controller's
/// step rate", which is asked for by *omitting* the parameter rather than by
/// sending the resolved cycle_time -- the api and sdk variants send the same
/// thing for the same setting, so a rate comparison compares only the client.
fn wire_rate(rate_ms: i32) -> Option<i32> {
    (rate_ms > 0).then_some(rate_ms)
}

/// Plan the up-and-back trajectory once, from the robot's current pose.
/// Server-side forward kinematics: the pose of the tool at `tcp_offset` for
/// the given joint position. Used to plan for a TCP that is not the active
/// one — never a hand-rolled pose composition (getting the rotation
/// composition subtly wrong moves physical robots to a wrong target).
async fn forward_kinematics(
    nova: &Nova,
    motion_group: &str,
    description: &t::MotionGroupDescription,
    joints: &t::Joints,
    tcp_offset: Option<t::Pose>,
) -> Result<t::Pose> {
    let response = nova
        .raw
        .forward_kinematics()
        .cell(&nova.cell)
        .body(t::ForwardKinematicsRequest {
            joint_positions: vec![t::DoubleArray(joints.0.clone())],
            motion_group_model: description.motion_group_model.clone(),
            mounting: description.mounting.clone(),
            tcp_offset,
        })
        .send()
        .await
        .with_context(|| format!("{motion_group}: forward_kinematics"))?
        .into_inner();
    response
        .tcp_poses
        .into_iter()
        .next()
        .ok_or_else(|| anyhow!("{motion_group}: forward_kinematics returned no pose"))
}

/// Largest position (mm) and rotation-vector (rad) component differences
/// between two poses.
fn pose_deviation(a: &t::Pose, b: &t::Pose) -> (f64, f64) {
    let component_max = |x: &[f64; 3], y: &[f64; 3]| {
        x.iter()
            .zip(y)
            .map(|(p, q)| (p - q).abs())
            .fold(0.0, f64::max)
    };
    let position = match (&a.position, &b.position) {
        (Some(p), Some(q)) => component_max(&p.0, &q.0),
        _ => f64::INFINITY,
    };
    let orientation = match (&a.orientation, &b.orientation) {
        (Some(p), Some(q)) => component_max(&p.0, &q.0),
        _ => f64::INFINITY,
    };
    (position, orientation)
}

const FK_POSITION_TOLERANCE_MM: f64 = 0.5;
const FK_ROTATION_TOLERANCE_RAD: f64 = 0.005;

/// Current pose of `tcp`. For the active TCP this is `state.tcp_pose`
/// directly. For any other configured TCP it is computed server-side via
/// forward kinematics — but only after verifying our FK usage against the
/// controller: FK with the *active* TCP's offset must reproduce
/// `state.tcp_pose` within tolerance, otherwise refuse.
async fn current_tcp_pose(
    nova: &Nova,
    motion_group: &str,
    description: &t::MotionGroupDescription,
    state: &t::MotionGroupState,
    tcp: &str,
    log: &RobotLog,
) -> Result<t::Pose> {
    let reported = state
        .tcp_pose
        .as_ref()
        .ok_or_else(|| anyhow!("{motion_group}: state carries no TCP pose, cannot plan"))?;
    if state.tcp.as_deref() == Some(tcp) {
        return Ok(reported.clone());
    }

    // Cross-check first: FK with the ACTIVE TCP's offset vs. the controller's
    // own report. If this diverges, our FK inputs (model/mounting/offset) are
    // wrong and the computed pose for `tcp` cannot be trusted either.
    let active = state.tcp.as_deref().ok_or_else(|| {
        anyhow!("{motion_group}: controller reports no active TCP, cannot verify FK")
    })?;
    let active_offset = description.tcps.get(active).map(|o| o.pose.clone());
    let check = forward_kinematics(
        nova,
        motion_group,
        description,
        &state.joint_position,
        active_offset,
    )
    .await?;
    let (position_dev, rotation_dev) = pose_deviation(&check, reported);
    if position_dev > FK_POSITION_TOLERANCE_MM || rotation_dev > FK_ROTATION_TOLERANCE_RAD {
        bail!(
            "{motion_group}: forward-kinematics cross-check failed for active TCP '{active}': \
             deviation {position_dev:.3} mm / {rotation_dev:.5} rad from state.tcp_pose — \
             refusing to plan for TCP '{tcp}' from an unverified FK"
        );
    }
    log.info(&format!(
        "{motion_group}: FK cross-check ok (active TCP '{active}', deviation \
         {position_dev:.3} mm / {rotation_dev:.5} rad); computing pose of TCP '{tcp}'"
    ));

    let offset = description.tcps.get(tcp).map(|o| o.pose.clone());
    forward_kinematics(
        nova,
        motion_group,
        description,
        &state.joint_position,
        offset,
    )
    .await
}

pub async fn plan_move_up(
    nova: &Nova,
    cfg: &Config,
    controller: &str,
    motion_group: &str,
    requested_tcp: Option<&str>,
    state_rate_ms: i32,
    log: &RobotLog,
) -> Result<Planned> {
    let started = Instant::now();
    let state = current_state(nova, controller, motion_group).await?;
    let description = get_description(nova, controller, motion_group).await?;

    // Requested (UI selection) → controller's active TCP → TCP env fallback.
    let tcp = requested_tcp
        .map(str::to_string)
        .or_else(|| state.tcp.clone())
        .unwrap_or_else(|| cfg.tcp.clone());
    if !description.tcps.contains_key(&tcp) {
        let mut available: Vec<_> = description.tcps.keys().cloned().collect();
        available.sort();
        bail!(
            "{motion_group}: TCP '{tcp}' is not configured on this controller \
             (available: {available:?}, active: {:?})",
            state.tcp
        );
    }

    let setup = build_setup(&description, &tcp, &state, log);
    let home = current_tcp_pose(nova, motion_group, &description, &state, &tcp, log).await?;

    let commands = up_and_back_commands(&home, DEFAULT_Z_OFFSET_MM)?;
    let segments = commands.len();
    let trajectory = plan(nova, motion_group, setup, &state.joint_position, commands).await?;
    log.info(&format!(
        "{motion_group}: planned {segments} segment(s) for TCP '{tcp}' in {:.2}s",
        started.elapsed().as_secs_f64()
    ));
    Ok(Planned {
        trajectory,
        response_rate: wire_rate(state_rate_ms),
        step_rate_ms: step_rate(&description),
        tcp,
    })
}

/// Plan the linear axis out-and-back move, from its current position. The axis
/// is its own motion group with a single prismatic joint, planned against TCP
/// "0". No TCP-consistency guard here, deliberately: a joint PTP is planned
/// from `state.joint_position`, so no tool frame enters the target.
pub async fn plan_axis_travel(
    nova: &Nova,
    controller: &str,
    motion_group: &str,
    state_rate_ms: i32,
    log: &RobotLog,
) -> Result<Planned> {
    let state = current_state(nova, controller, motion_group).await?;
    let description = get_description(nova, controller, motion_group).await?;
    let setup = build_setup(&description, AXIS_TCP, &state, log);

    let home = *state
        .joint_position
        .0
        .first()
        .ok_or_else(|| anyhow!("{motion_group}: axis reports no joint position"))?;
    let (lower, upper) = axis_limits(&setup)?;
    let target = compute_axis_target(home, DEFAULT_AXIS_TRAVEL_MM, lower, upper);
    log.info(&format!(
        "{motion_group}: axis home={home:.1} target={target:.1} (limits {lower:.1}..{upper:.1})"
    ));

    let commands = vec![joint_ptp(target), joint_ptp(home)];
    let trajectory = plan(nova, motion_group, setup, &state.joint_position, commands).await?;
    Ok(Planned {
        trajectory,
        response_rate: wire_rate(state_rate_ms),
        step_rate_ms: step_rate(&description),
        tcp: AXIS_TCP.to_string(),
    })
}

