// Execution
// ---------------------------------------------------------------------------

/// Return the error carried by an InitializeMovementResponse, if any. The
/// response is an acknowledgement, so its presence means "received", not
/// "accepted" — the failure hides in `add_trajectory_error`.
fn initialize_error(ack: &t::InitializeMovementResponse) -> Option<String> {
    if let Some(error) = &ack.add_trajectory_error {
        return Some(
            error
                .message
                .clone()
                .unwrap_or_else(|| format!("{error:?}")),
        );
    }
    ack.message.clone().filter(|m| !m.is_empty())
}

/// Largest per-joint deviation between the current and the planned final joint
/// position. Units are per-joint (rad for revolute, mm for prismatic).
fn deviation_from_target(state: &t::MotionGroupState, trajectory: &t::JointTrajectory) -> f64 {
    let Some(target) = trajectory.joint_positions.last() else {
        return 0.0;
    };
    state
        .joint_position
        .0
        .iter()
        .zip(target.0.iter())
        .map(|(current, planned)| (current - planned).abs())
        .fold(0.0, f64::max)
}

/// Execute a planned trajectory once and return how long it took.
///
/// Opens the state stream first (so no frame is lost), then the execution
/// websocket: Initialize (trajectory inline) → inspect the ack → Start → wait
/// for the state stream to report completion, draining the execution socket
/// for `MovementErrorResponse` in the meantime.
#[allow(clippy::too_many_arguments)] // mirrors the Python signature; a param struct would obscure the port
pub async fn execute_trajectory(
    nova: &Nova,
    controller: &str,
    motion_group: &str,
    planned: &Planned,
    timeout: Duration,
    cancel: &CancellationToken,
    log: &RobotLog,
) -> Result<f64> {
    let started = Instant::now();
    let cell = nova.client.cell(&nova.cell);

    let mut states = cell
        .motion_groups(controller)
        .state_stream(motion_group, planned.response_rate, None)
        .await
        .with_context(|| format!("{motion_group}: opening state stream"))?;

    let execution = cell
        .trajectory_execution()
        .execute_trajectory(controller)
        .await
        .with_context(|| format!("{motion_group}: opening execution websocket"))?;
    // Split so the response side is a poll-based Stream, which is safe to poll
    // inside select! without losing frames on branch cancellation.
    let (mut requests, mut responses) = execution.split();

    requests
        .send(&t::ExecuteTrajectoryRequest::InitializeMovementRequest(
            t::InitializeMovementRequest {
                message_type: t::InitializeMovementRequestMessageType::InitializeMovementRequest,
                trajectory: t::InitializeMovementRequestTrajectory::Data(t::TrajectoryData {
                    data: planned.trajectory.clone(),
                    message_type: t::TrajectoryDataMessageType::TrajectoryData,
                    motion_group: Some(motion_group.to_string()),
                    tcp: Some(planned.tcp.clone()),
                }),
                ignore_controller_limits: false,
                initial_location: Some(t::Location(0.0)),
                response_coordinate_system: None,
            },
        ))
        .await
        .with_context(|| format!("{motion_group}: sending InitializeMovementRequest"))?;

    // Wait for the initialize acknowledgement before starting, otherwise the
    // start can race the trajectory lock. The ack must be inspected, not just
    // awaited: a successful-looking INITIALIZE_RECEIVED can still carry an
    // add_trajectory_error (e.g. "TCP is not configured on controller").
    loop {
        let ack = tokio::select! {
            response = responses.next() => response,
            _ = cancel.cancelled() => bail!("{motion_group}: cancelled"),
            _ = tokio::time::sleep(timeout) => {
                bail!("{motion_group}: no initialize acknowledgement within {timeout:?}")
            }
        };
        match ack {
            Some(Ok(t::ExecuteTrajectoryResponse::InitializeMovementResponse(ack))) => {
                if let Some(error) = initialize_error(&ack) {
                    bail!("{motion_group}: initialize rejected: {error}");
                }
                break;
            }
            Some(Ok(t::ExecuteTrajectoryResponse::MovementErrorResponse(error))) => {
                bail!(
                    "{motion_group}: movement error during initialize: {}",
                    error.message
                )
            }
            Some(Ok(_)) => continue,
            Some(Err(error)) => {
                bail!("{motion_group}: execution websocket error during initialize: {error}")
            }
            None => bail!("{motion_group}: execution websocket closed during initialize"),
        }
    }

    requests
        .send(&t::ExecuteTrajectoryRequest::StartMovementRequest(
            t::StartMovementRequest {
                message_type: t::StartMovementRequestMessageType::StartMovementRequest,
                direction: None,
                target_location: None,
                set_outputs: vec![],
                start_on_io: None,
                pause_on_io: None,
            },
        ))
        .await
        .with_context(|| format!("{motion_group}: sending StartMovementRequest"))?;

    // The execution websocket has nothing left to tell us about completion, so
    // from here only the state stream decides; the socket is drained for
    // MovementErrorResponse.
    // Completion is decided by the execution FSM (a port of the SDK's
    // TrajectoryExecutionMachine with its wbr!2262 level-based guards — see
    // execution_fsm.rs). It is armed here, after StartMovementRequest went
    // out, matching the SDK's external `start` transition.
    let deadline = tokio::time::sleep(timeout);
    tokio::pin!(deadline);
    let mut frames: u64 = 0;
    let mut fsm = crate::execution_fsm::ExecutionFsm::new();
    let mut execution_open = true;

    loop {
        tokio::select! {
            state = states.next() => {
                let state = match state {
                    Some(Ok(state)) => state,
                    // A server error frame does not end the stream; log and go on.
                    Some(Err(error)) => {
                        log.warn(&format!("{motion_group}: state stream error frame: {error}"));
                        continue;
                    }
                    None => bail!(
                        "{motion_group}: state stream ended after {frames} frame(s) \
                         without reporting completion (controller disconnect?)"
                    ),
                };
                frames += 1;
                let signal = crate::execution_fsm::ExecuteSignal::from_state(&state);
                match fsm.process(signal, state.standstill) {
                    None => {}
                    Some(crate::execution_fsm::Outcome::Completed) => {
                        log.info(&format!(
                            "{motion_group}: trajectory ended after {frames} state frame(s)"
                        ));
                        break;
                    }
                    Some(crate::execution_fsm::Outcome::CompletedLegacy) => {
                        // Old-rae path: the execute block vanished at standstill
                        // without a terminal frame. Verify the end position —
                        // this signal cannot distinguish "done" from "stopped".
                        let deviation = deviation_from_target(&state, &planned.trajectory);
                        if deviation > 1.0 {
                            bail!(
                                "{motion_group}: motion stopped {deviation:.3} (rad/mm) short \
                                 of the planned target with the execute block cleared"
                            );
                        }
                        log.info(&format!(
                            "{motion_group}: execute block cleared at standstill after \
                             {frames} frame(s) (no TrajectoryEnded frame seen, \
                             deviation {deviation:.4})"
                        ));
                        break;
                    }
                    Some(crate::execution_fsm::Outcome::PausedAfterMotion) => {
                        bail!(
                            "{motion_group}: motion was paused at standstill after \
                             {frames} frame(s) — nothing in this app pauses, \
                             so something external did"
                        );
                    }
                }
            }
            response = responses.next(), if execution_open => {
                match response {
                    Some(Ok(t::ExecuteTrajectoryResponse::MovementErrorResponse(error))) => {
                        bail!("{motion_group}: movement error: {}", error.message)
                    }
                    Some(Ok(_)) => {}
                    Some(Err(error)) => {
                        log.warn(&format!(
                            "{motion_group}: execution websocket error, still watching the \
                             state stream: {error}"
                        ));
                        execution_open = false;
                    }
                    None => execution_open = false,
                }
            }
            _ = cancel.cancelled() => bail!("{motion_group}: cancelled"),
            _ = &mut deadline => {
                bail!(
                    "{motion_group}: no completion within {:.0}s ({frames} state frame(s) seen)",
                    timeout.as_secs_f64()
                )
            }
        }
    }

    let _ = requests.close().await;
    let elapsed = started.elapsed().as_secs_f64();
    log.info(&format!(
        "{motion_group}: motion completed in {elapsed:.2}s"
    ));
    Ok(elapsed)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn axis_target_moves_toward_farther_limit_and_clamps() {
        // limits of 1@ir350r01: -1854..321
        assert_eq!(compute_axis_target(-1800.0, 100.0, -1854.0, 321.0), -1700.0);
        assert_eq!(compute_axis_target(300.0, 100.0, -1854.0, 321.0), 200.0);
        // clamped at the upper end
        assert_eq!(compute_axis_target(-1500.0, 3000.0, -1854.0, 321.0), 321.0);
    }

    #[test]
    fn zero_asks_for_the_step_rate_by_omitting_response_rate() {
        // The whole point of 0: the request must be identical to the sdk and
        // api variants', which send no response_rate at all. Sending the
        // resolved cycle_time instead would put a difference into the thing
        // the three variants exist to compare.
        assert_eq!(wire_rate(0), None);
        assert_eq!(wire_rate(200), Some(200));
        assert_eq!(wire_rate(4), Some(4));
    }
}

//! Finite-state machine for one trajectory execution lifecycle.
//!
//! A port of the Python SDK's `TrajectoryExecutionMachine` from the
//! `fix/trajectory-completion-level-detection` branch (wandelbots-nova
//! PR #487, adapting to robotics/wbr!2262), including the level-based
//! guards from its `TrajectoryCursor`:
//!
//! - With the wbr!2262 rae image, the `execute` block is a **level**, not an
//!   event: it is published persistently from InitializeMovementRequest on
//!   (as `PausedByUser` while parked before the start) and the terminal
//!   `Ended` block persists after the motion — including into the next
//!   cycle's state stream until the next Initialize replaces it.
//! - Therefore the mere presence of an execute block is NOT evidence of
//!   execution. Evidence is `standstill == false` or a `Running` trajectory
//!   state (the SDK's `_frame_shows_motion`), and terminal states must not
//!   complete a motion that never moved.
//! - Old rae images (the customer IPC) instead drop the block the instant
//!   the robot settles, and the one-step terminal `Ended` frame can be lost
//!   entirely. The legacy completion path — execute block gone at standstill
//!   after motion was seen — is kept for those; on wbr!2262 it is inert
//!   because the block never disappears mid-lifecycle.
//!
//! State diagram (standstill = ss)::
//!
//!     executing ──ended, ss──────────────────→ ended
//!     executing ──ended, no ss──→ ending ──ss─→ ended
//!     executing ──paused-by-user, ss─────────→ paused   (after motion only)
//!     executing ──paused-by-user, no ss─→ pausing ──ss─→ paused
//!     executing ──no execute, ss, saw motion─→ ended    (legacy / old rae)
//!
//! `PausedOnIo` counts as an end (a planned stop point), like in the SDK.

use nova_client::types as t;

/// The trajectory-relevant content of one MotionGroupState frame.
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum ExecuteSignal {
    /// No execute block on the frame.
    Absent,
    /// Execute block present but not trajectory details (jogging) or with an
    /// unknown state — nothing to conclude.
    Other,
    Running,
    Ended,
    PausedByUser,
    PausedOnIo,
    WaitForIo,
}

impl ExecuteSignal {
    pub fn from_state(state: &t::MotionGroupState) -> Self {
        let Some(execute) = &state.execute else {
            return Self::Absent;
        };
        match &execute.details {
            Some(t::ExecuteDetails::TrajectoryDetails(details)) => match details.state {
                t::TrajectoryDetailsState::Running(_) => Self::Running,
                t::TrajectoryDetailsState::Ended(_) => Self::Ended,
                t::TrajectoryDetailsState::PausedByUser(_) => Self::PausedByUser,
                t::TrajectoryDetailsState::PausedOnIo(_) => Self::PausedOnIo,
                t::TrajectoryDetailsState::WaitForIo(_) => Self::WaitForIo,
            },
            _ => Self::Other,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Phase {
    Executing,
    /// Terminal trajectory state seen, waiting for standstill.
    Ending,
    /// PausedByUser seen after motion, waiting for standstill.
    Pausing,
}

/// What the caller must act on after feeding a frame.
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Outcome {
    /// Trajectory ended at standstill (`Ended`/`PausedOnIo` path).
    Completed,
    /// Execute block disappeared at standstill after motion was seen — the
    /// old-rae completion. The caller should verify the end position.
    CompletedLegacy,
    /// The motion was paused after it had been running — unexpected in this
    /// app, the caller decides (we treat it as a failure).
    PausedAfterMotion,
}

/// The machine is created when StartMovementRequest is sent (the SDK's
/// external `start` transition); `error` is represented by the caller
/// bailing, `idle` by the machine not existing yet.
pub struct ExecutionFsm {
    phase: Phase,
    /// The SDK's `_frame_shows_motion` latch: evidence that OUR motion is
    /// actually executing. Persistent pre-start `PausedByUser` levels and the
    /// previous trajectory's persistent `Ended` block never set it.
    saw_motion: bool,
}

impl ExecutionFsm {
    pub fn new() -> Self {
        Self {
            phase: Phase::Executing,
            saw_motion: false,
        }
    }

    #[cfg(test)]
    pub fn saw_motion(&self) -> bool {
        self.saw_motion
    }

    /// Feed one state frame; returns an outcome when the lifecycle concluded.
    pub fn process(&mut self, signal: ExecuteSignal, standstill: bool) -> Option<Outcome> {
        if !standstill || signal == ExecuteSignal::Running {
            self.saw_motion = true;
        }

        match self.phase {
