//! Per-robot log files with size-based rotation.
//!
//! Each robot task owns its own file under LOG_DIR — nothing per log line
//! passes through a shared channel or stdout, the same "keep the supervisor
//! out of the data path" rule the Python api app follows with per-process
//! RotatingFileHandlers. Size budget: robots × LOG_MAX_BYTES ×
//! (1 + LOG_BACKUP_COUNT) must stay under the 300Mi volume.

use std::fs::{File, OpenOptions};
use std::io::Write;
use std::path::PathBuf;
use std::sync::Mutex;

pub struct RobotLog {
    name: String,
    inner: Mutex<Inner>,
}

struct Inner {
    file: Option<File>,
    path: PathBuf,
    max_bytes: u64,
    backup_count: u32,
    written: u64,
}

impl RobotLog {
    pub fn open(dir: &str, controller: &str, max_bytes: u64, backup_count: u32) -> Self {
        let path = PathBuf::from(dir).join(format!("{controller}.log"));
        let _ = std::fs::create_dir_all(dir);
        let file = OpenOptions::new()
            .create(true)
            .append(true)
            .open(&path)
            .ok();
        let written = file
            .as_ref()
            .and_then(|f| f.metadata().ok())
            .map_or(0, |m| m.len());
        Self {
            name: controller.to_string(),
            inner: Mutex::new(Inner {
                file,
                path,
                max_bytes,
                backup_count,
                written,
            }),
        }
    }

    pub fn info(&self, message: &str) {
        self.write("INFO", message);
    }

    pub fn warn(&self, message: &str) {
        self.write("WARNING", message);
    }

    pub fn error(&self, message: &str) {
        self.write("ERROR", message);
    }

    fn write(&self, level: &str, message: &str) {
        let line = format!(
            "{} {level} {}: {message}\n",
            chrono::Utc::now().format("%Y-%m-%d %H:%M:%S%.3f"),
            self.name
        );
        let mut inner = self
            .inner
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        if inner.written + line.len() as u64 > inner.max_bytes {
            inner.rotate();
        }
        if let Some(file) = inner.file.as_mut() {
            if file.write_all(line.as_bytes()).is_ok() {
                inner.written += line.len() as u64;
            }
        }
    }
}

impl Inner {
    fn rotate(&mut self) {
        self.file = None;
        // <name>.log -> <name>.log.1 -> ... -> <name>.log.N, oldest dropped.
        for index in (1..self.backup_count).rev() {
            let from = self.path.with_extension(format!("log.{index}"));
            let to = self.path.with_extension(format!("log.{}", index + 1));
            let _ = std::fs::rename(from, to);
        }
        if self.backup_count > 0 {
            let _ = std::fs::rename(&self.path, self.path.with_extension("log.1"));
        } else {
            let _ = std::fs::remove_file(&self.path);
        }
        self.file = OpenOptions::new()
            .create(true)
            .append(true)
            .open(&self.path)
            .ok();
        self.written = 0;
    }
}

//! The per-robot worker: control mode → plan once → loop (check stop IO →
//! wait for start IO → execute arm and axis concurrently). A port of the
//! Python api app's `run_robot.py`, as one tokio task instead of one OS
//! process (the process split existed to keep 12 robots off one Python event
//! loop; tokio tasks on a multi-threaded runtime don't have that problem).
//!
//! Faithfully kept: any planning/execution failure ends the run — there is no
//! retry, the robot shows as failed until the operator presses Run again.
//! After a fault that needs manual intervention at the panel, a retry loop
//! would just re-fault the hardware.

use std::sync::Arc;
use std::time::Instant;

use anyhow::{Context, Result};
use nova_client::types as t;
use tokio_util::sync::CancellationToken;

use crate::busio::{self, IoHub};
use crate::config::Config;
use crate::discovery;
use crate::motion;
use crate::nova::Nova;
use crate::robotlog::RobotLog;
use crate::runner::{IoGate, Registry, RunOptions};

pub struct RobotCtx {
    pub nova: Nova,
    pub cfg: Config,
    pub hub: Arc<IoHub>,
    pub registry: Arc<Registry>,
    pub controller: String,
    /// TCP picked in the UI; None = the controller's active TCP.
    pub tcp: Option<String>,
    /// Wait/stop IOs for this run, editable in the UI (env config as default).
    pub gate: IoGate,
    /// Per-run options from the UI (env config as defaults).
    pub options: RunOptions,
    pub cancel: CancellationToken,
}

/// Check the stop IO. An unreadable IO never stops the run.
async fn should_stop(nova: &Nova, gate: &IoGate, log: &RobotLog) -> bool {
    let stop_io = &gate.stop_io;
    match busio::read_ios(nova, std::slice::from_ref(stop_io)).await {
        Ok(values) => values.get(stop_io) == Some(&serde_json::json!(gate.stop_io_value)),
        Err(error) => {
            log.warn(&format!("could not read stop IO '{stop_io}': {error:#}"));
            false
        }
    }
}

pub async fn run(ctx: RobotCtx) {
    let controller = ctx.controller.clone();
    let log = RobotLog::open(
        &ctx.cfg.log_dir,
        &controller,
        ctx.cfg.log_max_bytes,
        ctx.cfg.log_backup_count,
    );

    let outcome = run_inner(&ctx, &log).await;
    match outcome {
        Ok(cycles) => {
            log.info(&format!("{controller}: finished after {cycles} cycle(s)"));
            ctx.registry.update(&controller, |s| {
                s.running = false;
                s.state = "finished".to_string();
                s.finished_at = Some(chrono::Utc::now());
            });
        }
        Err(error) => {
            if ctx.cancel.is_cancelled() {
                log.info(&format!("{controller}: stopped ({error:#})"));
                ctx.registry.update(&controller, |s| {
                    s.running = false;
                    s.state = "stopped".to_string();
                    s.finished_at = Some(chrono::Utc::now());
                });
            } else {
                // The supervisor does not read robot errors from anywhere else,
                // and a crash is exactly what this app is hunting — log it in
                // full before surfacing it in the status.
                log.error(&format!("{controller}: run failed: {error:#}"));
                tracing::error!(controller, error = format!("{error:#}"), "robot run failed");
                ctx.registry.update(&controller, |s| {
                    s.running = false;
                    s.state = "failed".to_string();
                    s.errors += 1;
                    s.last_error = Some(format!("{error:#}"));
                    s.finished_at = Some(chrono::Utc::now());
                });
            }
        }
    }
}

async fn run_inner(ctx: &RobotCtx, log: &RobotLog) -> Result<u64> {
    let RobotCtx {
        nova,
        cfg,
        hub,
        registry,
        controller,
        tcp,
        gate,
        options,
        cancel,
    } = ctx;

    registry.update(controller, |s| s.state = "discovering".to_string());
    let motion_group = discovery::arm_motion_group(controller);
    let has_axis = discovery::has_linear_axis(nova, controller).await;
    log.info(&format!(
        "{controller}: starting (motion_group={motion_group}, linear_axis={has_axis}, \
         wait_io={}=={}, stop_io={}=={}, tcp={})",
        gate.wait_io,
        gate.wait_io_value,
        gate.stop_io,
        gate.stop_io_value,
        tcp.as_deref().unwrap_or("<active>")
    ));
    registry.update(controller, |s| s.linear_axis = Some(has_axis));

    nova.raw
        .set_default_mode()
        .cell(&nova.cell)
        .controller(controller)
        .mode(t::SettableRobotSystemMode::ModeControl)
        .send()
        .await
        .map_err(|e| anyhow::anyhow!("{controller}: set_default_mode: {e}"))?;

    // Plan both motion groups once, before the signal loop.
    registry.update(controller, |s| s.state = "planning".to_string());
    let axis_group = has_axis.then(|| discovery::axis_motion_group(controller));
    let planned = motion::plan_move_up(
        nova,
        cfg,
        controller,
        &motion_group,
        tcp.as_deref(),
        options.state_rate_ms,
        log,
    )
    .await?;
    registry.update(controller, |s| s.tcp = Some(planned.tcp.clone()));
    let axis_planned = match &axis_group {
        Some(axis) => Some(
            motion::plan_axis_travel(nova, controller, axis, options.state_rate_ms, log).await?,
        ),
        None => None,
    };
    log.info(&format!(
        "{controller}: state stream rate {}",
        match planned.response_rate {
            Some(ms) => format!("{ms} ms (requested)"),
            None => format!(
                "controller step rate (~{} ms, response_rate omitted)",
                planned.step_rate_ms
            ),
        }
    ));

    let mut cycle: u64 = 0;
    let mut motion_seconds_total = 0.0_f64;
    loop {
        if cancel.is_cancelled() {
            anyhow::bail!("cancelled");
        }
        if should_stop(nova, gate, log).await {
            log.info(&format!(
                "{controller}: stop IO '{}' is {}, exiting loop",
                gate.stop_io, gate.stop_io_value
            ));
            break;
        }

        cycle += 1;
        registry.update(controller, |s| {
            s.cycle = cycle;
            s.state = "waiting for start".to_string();
        });
        log.info(&format!(
            "{controller}: cycle {cycle} - waiting for IO '{}'",
            gate.wait_io
        ));
        let waited = Instant::now();
        busio::wait_for_io(hub, nova, &gate.wait_io, gate.wait_io_value, cancel, log)
            .await
            .with_context(|| {
                format!(
                    "wait IO '{}' could not be waited for — does it exist on this cell? \
                     Pick an existing bus IO in the UI's run-gating inputs",
                    gate.wait_io
                )
            })?;
        log.info(&format!(
            "{controller}: cycle {cycle} - start signal after {:.2}s, executing",
            waited.elapsed().as_secs_f64()
        ));

        // Arm and axis move simultaneously, as two concurrent executions on
        // the same controller — same shape as the Python apps' TaskGroup.
        registry.update(controller, |s| s.state = "moving".to_string());
        let started = Instant::now();
        let arm = motion::execute_trajectory(
            nova,
            controller,
            &motion_group,
            &planned,
            cfg.motion_timeout,
            cancel,
            log,
        );
        let motion_s = match (&axis_group, &axis_planned) {
            (Some(axis), Some(axis_planned)) => {
                let axis_run = motion::execute_trajectory(
                    nova,
                    controller,
                    axis,
                    axis_planned,
                    cfg.motion_timeout,
                    cancel,
                    log,
                );
                let (arm_s, _axis_s) = tokio::try_join!(arm, axis_run)?;
                arm_s
            }
            _ => arm.await?,
        };

        motion_seconds_total += motion_s;
        let cycle_s = started.elapsed().as_secs_f64();
        registry.update(controller, |s| {
            s.last_cycle_s = Some(cycle_s);
            s.avg_motion_s = Some(motion_seconds_total / cycle as f64);
        });
        log.info(&format!(
            "{controller}: cycle {cycle} complete (motion {cycle_s:.2}s)"
        ));
    }
    Ok(cycle)
}
