//! The supervisor: spawn robot tasks, track their status, stop them.
//!
//! Operational semantics kept from the Python api app (don't "fix" these):
//! - `start` is incremental: a controller whose task is still alive is
//!   skipped, so re-pressing "Run selected" with everything checked only adds
//!   the new ones.
//! - Unchecking a robot does not stop it; stopping is its own action.
//! - A robot that has exited gets respawned by the next start if selected.
//!
//! Status lives in a shared registry the UI reads; robot tasks update it and
//! bump a watch channel so the status SSE stream pushes on change instead of
//! the browser polling.

use std::collections::HashMap;
use std::sync::{Arc, Mutex, RwLock};

use serde::Serialize;
use tokio::sync::watch;
use tokio_util::sync::CancellationToken;
use tokio_util::task::TaskTracker;

use crate::busio::{IoHub, StatusPublisher};
use crate::config::Config;
use crate::nova::Nova;
use crate::robot::{self, RobotCtx};

#[derive(Clone, Serialize, Default)]
pub struct RobotStatus {
    pub controller: String,
    pub state: String,
    pub running: bool,
    pub cycle: u64,
    pub errors: u64,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub last_error: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub last_cycle_s: Option<f64>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub avg_motion_s: Option<f64>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub linear_axis: Option<bool>,
    /// The TCP the arm trajectory was planned and executed with.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub tcp: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub started_at: Option<chrono::DateTime<chrono::Utc>>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub finished_at: Option<chrono::DateTime<chrono::Utc>>,
}

/// Shared robot status map. Every update bumps `changed` so SSE consumers can
/// push a fresh snapshot; reading is a plain lock, never a round trip. The
/// same snapshot is also handed to the NATS `StatusPublisher` (fire-and-forget,
/// see busio.rs) so the bus carries what the local SSE stream carries.
pub struct Registry {
    statuses: RwLock<HashMap<String, RobotStatus>>,
    changed: watch::Sender<u64>,
    publisher: Option<Arc<StatusPublisher>>,
}

impl Registry {
    pub fn new(publisher: Option<Arc<StatusPublisher>>) -> Arc<Self> {
        Arc::new(Self {
            statuses: RwLock::new(HashMap::new()),
            changed: watch::channel(0).0,
            publisher,
        })
    }

    pub fn update(&self, controller: &str, apply: impl FnOnce(&mut RobotStatus)) {
        let snapshot = {
            let mut statuses = self.statuses.write().unwrap_or_else(|p| p.into_inner());
            let status = statuses
                .entry(controller.to_string())
                .or_insert_with(|| RobotStatus {
                    controller: controller.to_string(),
                    ..RobotStatus::default()
                });
            apply(status);
            status.clone()
        };
        self.changed.send_modify(|version| *version += 1);

        if let Some(publisher) = &self.publisher {
            // Tagged with the app so consumers can tell the three ARG3
            // variants apart on one cell; `publish` never blocks.
            if let Ok(mut value) = serde_json::to_value(&snapshot) {
                value["app"] = serde_json::json!("audi-arg3-rust");
                publisher.publish(value.to_string());
            }
        }
    }

    pub fn snapshot(&self) -> Vec<RobotStatus> {
        let statuses = self.statuses.read().unwrap_or_else(|p| p.into_inner());
        let mut list: Vec<_> = statuses.values().cloned().collect();
        list.sort_by(|a, b| a.controller.cmp(&b.controller));
        list
    }

    pub fn watch(&self) -> watch::Receiver<u64> {
        self.changed.subscribe()
    }
}

/// One robot the operator asked to start: controller name plus the TCP picked
/// in the UI (None = the controller's active TCP).
#[derive(serde::Deserialize)]
pub struct RobotStart {
    pub name: String,
    #[serde(default)]
    pub tcp: Option<String>,
}

/// The run gate: which bus IOs enable and stop the loop. Editable per run in
/// the UI — the same mechanism as the SDK app's wait_io/stop_io program
/// arguments — with the env config as defaults.
#[derive(Clone, serde::Serialize)]
pub struct IoGate {
    pub wait_io: String,
    pub wait_io_value: bool,
    pub stop_io: String,
    pub stop_io_value: bool,
}

/// Variant-specific per-run options from the UI (see web.rs's /api/config
/// `run_options`): here only the state-stream rate, the knob the three
/// variants exist to compare.
#[derive(Clone, Copy, serde::Serialize)]
pub struct RunOptions {
    /// State-stream rate in ms; 0 means the controller's step rate, requested
    /// by omitting `response_rate` (see motion::wire_rate).
    pub state_rate_ms: i32,
}

struct RobotHandle {
    cancel: CancellationToken,
    join: tokio::task::JoinHandle<()>,
}

pub struct Runner {
    nova: Nova,
    cfg: Config,
    hub: Arc<IoHub>,
    pub registry: Arc<Registry>,
    robots: Mutex<HashMap<String, RobotHandle>>,
    tracker: TaskTracker,
    shutdown: CancellationToken,
}

impl Runner {
    pub fn new(
        nova: Nova,
        cfg: Config,
        hub: Arc<IoHub>,
        publisher: Option<Arc<StatusPublisher>>,
        shutdown: CancellationToken,
    ) -> Arc<Self> {
        Arc::new(Self {
            nova,
            cfg,
            hub,
            registry: Registry::new(publisher),
            robots: Mutex::new(HashMap::new()),
            tracker: TaskTracker::new(),
            shutdown,
        })
    }

    /// Start the loop for each controller that is not already running.
    /// Returns the controllers actually started.
    pub fn start(
        self: &Arc<Self>,
        robots_to_start: Vec<RobotStart>,
        gate: IoGate,
        options: RunOptions,
    ) -> Vec<String> {
        let mut robots = self.robots.lock().unwrap_or_else(|p| p.into_inner());
        let mut started = Vec::new();
        for RobotStart {
            name: controller,
            tcp,
        } in robots_to_start
        {
            if let Some(handle) = robots.get(&controller) {
                if !handle.join.is_finished() {
                    continue; // already running — adding robots is incremental
                }
            }
            let cancel = self.shutdown.child_token();
            self.registry.update(&controller, |s| {
                s.running = true;
                s.state = "starting".to_string();
                s.last_error = None;
                s.started_at = Some(chrono::Utc::now());
                s.finished_at = None;
                s.cycle = 0;
                s.last_cycle_s = None;
                s.avg_motion_s = None;
                s.tcp = None;
            });
            let ctx = RobotCtx {
                nova: self.nova.clone(),
                cfg: self.cfg.clone(),
                hub: self.hub.clone(),
                registry: self.registry.clone(),
                controller: controller.clone(),
                tcp,
                gate: gate.clone(),
                options,
                cancel: cancel.clone(),
            };
            let join = self.tracker.spawn(robot::run(ctx));
            robots.insert(controller.clone(), RobotHandle { cancel, join });
            started.push(controller);
        }
        started
    }

    /// Stop the given controllers, or all of them when `controllers` is None.
    /// Robots observe the cancellation at their next await point.
    pub fn stop(&self, controllers: Option<Vec<String>>) -> Vec<String> {
        let robots = self.robots.lock().unwrap_or_else(|p| p.into_inner());
        let mut stopped = Vec::new();
        for (controller, handle) in robots.iter() {
            let selected = controllers
                .as_ref()
                .is_none_or(|list| list.contains(controller));
            if selected && !handle.join.is_finished() {
                handle.cancel.cancel();
                stopped.push(controller.clone());
            }
        }
        stopped
    }

    pub fn any_running(&self) -> bool {
        let robots = self.robots.lock().unwrap_or_else(|p| p.into_inner());
        robots.values().any(|handle| !handle.join.is_finished())
    }

    /// Cancel everything and wait for the robot tasks to unwind (used on
    /// shutdown, bounded by the caller).
    pub async fn shutdown(&self) {
        self.stop(None);
        self.tracker.close();
        self.tracker.wait().await;
    }
}

//! The operator UI and its JSON API. Same rule as the Python api app: while
//! robots are running, the UI must not make the app do work per motion, per
//! log line or per state frame. IO changes and robot status are pushed over
//! SSE (fed from NATS and the in-process registry — both cost nothing while
//! idle); logs stay on disk and are read back from it in bounded windows,
//! only while the operator is looking.

