/// Effective defaults the UI prefills its run-gating inputs with, plus the one
/// thing that tells the shared frontend (ui/ at the repo root, copied into
/// static/) which variant it is talking to: the label and accent colour key.
/// `run_options` carries the variant-specific per-run switches; all three
/// variants offer the state-stream rate, with the same 0 = step rate meaning.
/// `log_view` tells the UI this backend serves the bounded log endpoints; a
/// backend without them omits the key and its Logs panel stays exactly as it
/// was.
async fn config_defaults(State(state): State<AppState>) -> Json<serde_json::Value> {
    Json(json!({
        "wait_io": state.cfg.wait_io,
        "stop_io": state.cfg.stop_io,
        "variant": {
            "key": "rust",
            "label": "Rust",
            "tech": "Rust client (vendored), one tokio task per robot",
        },
        "run_options": [state_rate_option(state.cfg.state_response_rate_ms)],
        "log_view": { "follow": true },
    }))
}

/// The state-stream rate as a per-run UI option. Identical in all three
/// variants (same name, same units, same 0), so a rate comparison is one
/// number typed into the same box.
fn state_rate_option(default_ms: i32) -> serde_json::Value {
    json!({
        "name": "state_rate_ms",
        "label": "state stream rate (ms, 0 = step rate)",
        "type": "number",
        "min": 0,
        "step": 1,
        "default": default_ms,
        "hint": "Motion-group state stream response_rate. 0 omits the parameter, \
                 so the controller streams at its own step rate.",
    })
}

/// Read `state_rate_ms` out of the UI's `options` object. The shared UI sends
/// every non-checkbox option as a string, so accept both.
fn state_rate_from_options(
    options: &serde_json::Map<String, serde_json::Value>,
    default_ms: i32,
) -> Result<i32, String> {
    let Some(value) = options.get("state_rate_ms") else {
        return Ok(default_ms);
    };
    let parsed = match value {
        serde_json::Value::Null => return Ok(default_ms),
        serde_json::Value::Number(number) => number.as_i64(),
        serde_json::Value::String(text) if text.trim().is_empty() => return Ok(default_ms),
        serde_json::Value::String(text) => text.trim().parse::<i64>().ok(),
        _ => None,
    };
    match parsed {
        Some(ms) if (0..=60_000).contains(&ms) => Ok(ms as i32),
        _ => Err(format!(
            "state_rate_ms must be a whole number of milliseconds between 0 and 60000, got {value}"
        )),
    }
}

/// All boolean bus IOs of the cell, for the run-gating input suggestions.
async fn io_descriptions(State(state): State<AppState>) -> Response {
    match state
        .nova
        .raw
        .list_bus_io_descriptions()
        .cell(&state.nova.cell)
        .send()
        .await
    {
        Ok(response) => {
            let ios: Vec<_> = response
                .into_inner()
                .0
                .into_iter()
                .filter(|d| d.value_type == nova_client::types::IoValueType::IoValueBoolean)
                .map(|d| {
                    json!({
                        "io": d.io,
                        "name": d.name,
                        "direction": d.direction.to_string(),
                    })
                })
                .collect();
            Json(ios).into_response()
        }
        Err(error) => error_response(StatusCode::BAD_GATEWAY, error),
    }
}

#[derive(Deserialize)]
struct IosCreateRequest {
    ios: Vec<String>,
    #[serde(default)]
    create_service: bool,
}

/// Create the run-gate IOs on the cell's (virtual) bus-IO service.
async fn ios_create(State(state): State<AppState>, Json(body): Json<IosCreateRequest>) -> Response {
    let mut names: Vec<String> = body
        .ios
        .into_iter()
        .map(|io| io.trim().to_string())
        .filter(|io| !io.is_empty())
        .collect();
    names.dedup();
    if names.is_empty() {
        return error_response(StatusCode::BAD_REQUEST, "no IO names given");
    }
    match crate::iocreate::create_gate_ios(&state.nova, &names, body.create_service).await {
        Ok(report) => Json(serde_json::to_value(report).unwrap_or_default()).into_response(),
        Err(crate::iocreate::CreateError::NoService) => (
            StatusCode::CONFLICT,
            Json(json!({
                "error": "no_service",
                "detail": "no bus-IO service configured on this cell",
            })),
        )
            .into_response(),
        Err(error) => error_response(StatusCode::BAD_GATEWAY, error),
    }
}

/// Delete the named IOs from the cell's (virtual) bus-IO service.
async fn ios_delete(State(state): State<AppState>, Json(body): Json<IosCreateRequest>) -> Response {
    let mut names: Vec<String> = body
        .ios
        .into_iter()
        .map(|io| io.trim().to_string())
        .filter(|io| !io.is_empty())
        .collect();
    names.dedup();
    if names.is_empty() {
        return error_response(StatusCode::BAD_REQUEST, "no IO names given");
    }
    match crate::iocreate::delete_gate_ios(&state.nova, &names).await {
        Ok(report) => Json(serde_json::to_value(report).unwrap_or_default()).into_response(),
        Err(error) => error_response(StatusCode::BAD_GATEWAY, error),
    }
}

/// Every probe is bounded and every failure is returned as text — a
/// diagnostic that hangs (or raises) diagnoses nothing.
async fn health(State(state): State<AppState>) -> Json<serde_json::Value> {
    const PROBE_TIMEOUT: Duration = Duration::from_secs(8);

    let mut nova_error = None;
    let mut cells_visible = None;
    let mut controllers: Option<Vec<String>> = None;

    match tokio::time::timeout(PROBE_TIMEOUT, state.nova.client.system().list_cells()).await {
        Ok(Ok(cells)) => cells_visible = Some(cells.0),
        Ok(Err(error)) => nova_error = Some(format!("{error}")),
        Err(_) => nova_error = Some(format!("list_cells: no answer within {PROBE_TIMEOUT:?}")),
    }
    if nova_error.is_none() {
        match tokio::time::timeout(PROBE_TIMEOUT, discovery::list_controllers(&state.nova)).await {
            Ok(Ok(names)) => controllers = Some(names),
            Ok(Err(error)) => nova_error = Some(format!("{error:#}")),
            Err(_) => {
                nova_error = Some(format!(
                    "list_controllers: no answer within {PROBE_TIMEOUT:?}"
                ))
            }
        }
    }

    let hint = if nova_error.is_some() {
        Some("NOVA_API is unreachable or wrong — check the effective value below")
    } else if controllers.as_ref().is_some_and(Vec::is_empty) {
        Some("API reachable but no controllers in this cell — wrong cell name or instance?")
    } else if !state.hub.connected() {
        Some("API fine but NATS down — IO waits fall back to 1s polling until it reconnects")
    } else if state.publisher.disabled() {
        Some("NATS refused status publishing — set STATUS_SUBJECT to a permitted subject (the UI's own SSE is unaffected)")
    } else {
        None
    };

    let status_publish = if state.publisher.disabled() {
        "disabled (server refused)"
    } else if state.publisher.connected() {
        "connected"
    } else {
        "connecting"
    };

    Json(json!({
        "nova_api": state.cfg.nova_api,
        "cell": state.cfg.cell,
        "nats_url": state.hub.url(),
        "status_subject": state.publisher.subject(),
        "status_publish": status_publish,
        "status_publish_error": state.publisher.last_error(),
        "log_dir": state.cfg.log_dir,
        "tcp": state.cfg.tcp,
        "state_response_rate_ms":
            if state.cfg.state_response_rate_ms > 0 { json!(state.cfg.state_response_rate_ms) }
            else { json!("controller step rate") },
        "cells_visible": cells_visible,
        "controllers": controllers,
        "controller_count": controllers.as_ref().map(Vec::len),
        "nova_error": nova_error,
        "nats_connected": state.hub.connected(),
        "nats_error": state.hub.last_error(),
        "hint": hint,
    }))
}

/// Parse `?io=a&io=b` (repeated key) from the raw query string.
fn tracked_ios(query: Option<&str>) -> Vec<String> {
    let Some(query) = query else {
        return Vec::new();
    };
    query
        .split('&')
        .filter_map(|pair| pair.split_once('='))
        .filter(|(key, _)| *key == "io" || *key == "ios")
        .filter_map(|(_, value)| {
            let value = value.trim();
            (!value.is_empty()).then(|| value.to_string())
        })
        .collect()
}

async fn read_ios(State(state): State<AppState>, RawQuery(query): RawQuery) -> Response {
    let ios = tracked_ios(query.as_deref());
    if ios.is_empty() {
        return Json(json!({})).into_response();
    }
    match busio::read_ios(&state.nova, &ios).await {
        Ok(values) => Json(values).into_response(),
        Err(error) => error_response(StatusCode::BAD_GATEWAY, error),
    }
}

