        Err(error) => error_response(StatusCode::BAD_GATEWAY, error),
    }
}

async fn ios_stream(
    State(state): State<AppState>,
    RawQuery(query): RawQuery,
) -> Sse<impl Stream<Item = Result<Event, Infallible>>> {
    let tracked: HashSet<String> = tracked_ios(query.as_deref()).into_iter().collect();
    let stream = BroadcastStream::new(state.hub.subscribe()).filter_map(move |change| {
        let tracked = tracked.clone();
        async move {
            match change {
                Ok((io, value)) if tracked.is_empty() || tracked.contains(&io) => {
                    Some(Ok(Event::default().data(json!({ io: value }).to_string())))
                }
                _ => None, // untracked IO or lag — the browser re-reads on demand
            }
        }
    });
    Sse::new(stream).keep_alive(KeepAlive::new().interval(Duration::from_secs(15)))
}

fn run_snapshot(state: &AppState) -> serde_json::Value {
    json!({
        "any_running": state.runner.any_running(),
        "robots": state.runner.registry.snapshot(),
    })
}

async fn run_status(State(state): State<AppState>) -> Json<serde_json::Value> {
    Json(run_snapshot(&state))
}

#[derive(Deserialize, Default)]
struct RunRequest {
    /// Robots to start, each with the TCP picked in the UI (optional — None
    /// means the controller's active TCP).
    #[serde(default)]
    controllers: Option<Vec<crate::runner::RobotStart>>,
    /// Run gate overrides; env config fills whatever is omitted. Same
    /// mechanism as the SDK app's wait_io/stop_io program arguments.
    #[serde(default)]
    wait_io: Option<String>,
    #[serde(default)]
    wait_io_value: Option<bool>,
    #[serde(default)]
    stop_io: Option<String>,
    #[serde(default)]
    stop_io_value: Option<bool>,
    /// Variant-specific per-run options from the UI (`run_options` in
    /// /api/config); values arrive as strings for everything but checkboxes.
    #[serde(default)]
    options: Option<serde_json::Map<String, serde_json::Value>>,
}

async fn run_start(State(state): State<AppState>, Json(body): Json<RunRequest>) -> Response {
    let controllers = body.controllers.unwrap_or_default();
    if controllers.is_empty() {
        return error_response(StatusCode::BAD_REQUEST, "no controllers selected");
    }
    let gate = crate::runner::IoGate {
        wait_io: body
            .wait_io
            .filter(|io| !io.trim().is_empty())
            .unwrap_or_else(|| state.cfg.wait_io.clone()),
        wait_io_value: body.wait_io_value.unwrap_or(true),
        stop_io: body
            .stop_io
            .filter(|io| !io.trim().is_empty())
            .unwrap_or_else(|| state.cfg.stop_io.clone()),
        stop_io_value: body.stop_io_value.unwrap_or(true),
    };
    let options = body.options.unwrap_or_default();
    let state_rate_ms = match state_rate_from_options(&options, state.cfg.state_response_rate_ms) {
        Ok(rate) => rate,
        Err(error) => return error_response(StatusCode::BAD_REQUEST, error),
    };
    let started = state.runner.start(
        controllers,
        gate,
        crate::runner::RunOptions { state_rate_ms },
    );
    Json(json!({ "started": started })).into_response()
}

#[derive(Deserialize, Default)]
struct StopRequest {
    #[serde(default)]
    controllers: Option<Vec<String>>,
}

async fn run_stop(
    State(state): State<AppState>,
    body: Option<Json<StopRequest>>,
) -> Json<serde_json::Value> {
    let controllers = body
        .and_then(|Json(b)| b.controllers)
        .filter(|c| !c.is_empty());
    let stopped = state.runner.stop(controllers);
    Json(json!({ "stopped": stopped }))
}

/// Push the full status snapshot whenever any robot status changes, throttled
/// so a burst of updates costs one message. The watch channel always yields
/// the latest version, so nothing is lost by throttling.
async fn status_stream(
    State(state): State<AppState>,
) -> Sse<impl Stream<Item = Result<Event, Infallible>>> {
    let watch = state.runner.registry.watch();
    let stream =
        tokio_stream::StreamExt::throttle(WatchStream::new(watch), Duration::from_millis(300));
    let stream = StreamExt::map(stream, move |_version| {
        Ok(Event::default().data(run_snapshot(&state).to_string()))
    });
    Sse::new(stream).keep_alive(KeepAlive::new().interval(Duration::from_secs(15)))
}

