/// Parse `?offset=&limit=` by hand rather than through `Query`, whose
/// rejection is plain text — every error this app returns is
/// `{"detail": "<string>"}`, and the three Python siblings must match.
fn view_params(query: Option<&str>) -> Result<(Option<u64>, Option<u64>), String> {
    let mut offset = None;
    let mut limit = None;
    for (key, value) in query
        .unwrap_or("")
        .split('&')
        .filter_map(|pair| pair.split_once('='))
    {
        let slot = match key {
            "offset" => &mut offset,
            "limit" => &mut limit,
            _ => continue, // unknown keys are ignored, as elsewhere in this app
        };
        let value = value.trim();
        if value.is_empty() {
            continue;
        }
        *slot = Some(
            value
                .parse::<u64>()
                .map_err(|_| format!("{key} must be a non-negative integer"))?,
        );
    }
    Ok((offset, limit))
}

/// A bounded window of one log file. Replaces reading the whole thing: a log
/// is LOG_MAX_BYTES (10 MB by default) and the viewer only ever shows a slice.
async fn logs_view(
    State(state): State<AppState>,
    Path(name): Path<String>,
    RawQuery(query): RawQuery,
) -> Response {
    let (offset, limit) = match view_params(query.as_deref()) {
        Ok(params) => params,
        Err(error) => return error_response(StatusCode::BAD_REQUEST, error),
    };
    let Some(path) = logsfs::resolve(&state.cfg.log_dir, &name) else {
        return error_response(StatusCode::NOT_FOUND, format!("no log file '{name}'"));
    };
    let Ok(metadata) = tokio::fs::metadata(&path).await else {
        // Raced with clear_logs(): the file is gone, which is a 404, not a 500.
        return error_response(StatusCode::NOT_FOUND, format!("no log file '{name}'"));
    };
    let size = metadata.len();
    let (off, end0) = logsfs::window(size, offset, limit);
    let buffer = match logsfs::read_window(&path, off, end0.saturating_sub(off)).await {
        Ok(buffer) => buffer,
        Err(_) => return error_response(StatusCode::NOT_FOUND, format!("no log file '{name}'")),
    };
    let (start, end, text, partial) = logsfs::trim_to_lines(&buffer, off, end0, size);
    Json(logsfs::LogView {
        name,
        size,
        start,
        end,
        text,
        bof: start == 0,
        eof: end == size,
        partial,
    })
    .into_response()
}

/// Follow one log file. Opt-in and short-lived: the browser opens this only
/// while the viewer pane is open and "follow" is ticked, and closes it the
/// moment either stops being true. Nothing runs per log line on the writer's
/// path — this polls the file's own size from the reader's side.
async fn logs_stream(
    State(state): State<AppState>,
    Path(name): Path<String>,
    RawQuery(query): RawQuery,
) -> Response {
    let offset = match view_params(query.as_deref()) {
        Ok((offset, _)) => offset,
        Err(error) => return error_response(StatusCode::BAD_REQUEST, error),
    };
    // The only chance to answer with a status code; everything after the
    // stream opens has to be reported in-band.
    let Some(path) = logsfs::resolve(&state.cfg.log_dir, &name) else {
        return error_response(StatusCode::NOT_FOUND, format!("no log file '{name}'"));
    };
    let size = tokio::fs::metadata(&path)
        .await
        .map(|m| m.len())
        .unwrap_or(0);

    struct Follow {
        path: std::path::PathBuf,
        cursor: u64,
        missing_since: Option<std::time::Instant>,
        done: bool,
    }

    let state = Follow {
        path,
        cursor: offset.unwrap_or(size),
        missing_since: None,
        done: false,
    };

    let stream = futures_util::stream::unfold(state, |mut follow| async move {
        if follow.done {
            return None;
        }
        loop {
            tokio::time::sleep(logsfs::FOLLOW_INTERVAL).await;

            // Stat the PATH, never a held descriptor: both writers rotate by
            // rename+recreate, so a descriptor we kept open would go on
            // reading the renamed `.log.1` and never see the rotation.
            let size = match tokio::fs::metadata(&follow.path).await {
                Ok(metadata) => {
                    follow.missing_since = None;
                    metadata.len()
                }
                Err(_) => {
                    let since = *follow
                        .missing_since
                        .get_or_insert_with(std::time::Instant::now);
                    if since.elapsed() < logsfs::GONE_GRACE {
                        continue; // mid-rotation; the recreate lands in a moment
                    }
                    follow.done = true;
                    let event = Event::default().data(json!({ "type": "gone" }).to_string());
                    return Some((Ok::<Event, Infallible>(event), follow));
                }
            };

            let (from, len, skipped) = match logsfs::follow_step(
                follow.cursor,
                size,
                logsfs::FOLLOW_CHUNK_BYTES,
                logsfs::FOLLOW_MAX_LAG_BYTES,
            ) {
                logsfs::FollowStep::Idle => continue,
                logsfs::FollowStep::Rotated { size } => {
                    follow.cursor = 0;
                    let event = Event::default()
                        .data(json!({ "type": "rotated", "size": size }).to_string());
                    return Some((Ok(event), follow));
                }
                logsfs::FollowStep::Read { from, len } => (from, len, 0),
                logsfs::FollowStep::Gap { from, len, skipped } => (from, len, skipped),
            };

            let Ok(buffer) = logsfs::read_window(&follow.path, from, len).await else {
                continue; // a rename landed between stat and open; next tick sees it
            };
            // Emit whole lines only. A torn trailing line waits for the next
            // tick, unless it alone fills a chunk and would stall the stream.
            let keep = match buffer.iter().rposition(|&b| b == b'\n') {
                Some(j) => j + 1,
                None if buffer.len() as u64 >= logsfs::FOLLOW_CHUNK_BYTES => buffer.len(),
                None => continue,
            };
            let text = String::from_utf8_lossy(&buffer[..keep]).into_owned();
            let end = from + keep as u64;
            follow.cursor = end;
            let payload = if skipped > 0 {
                json!({ "type": "gap", "start": from, "end": end, "skipped": skipped, "text": text })
            } else {
                json!({ "type": "append", "start": from, "end": end, "text": text })
            };
            return Some((Ok(Event::default().data(payload.to_string())), follow));
        }
    });

    let sse = Sse::new(stream).keep_alive(KeepAlive::new().interval(Duration::from_secs(15)));
    (
        [
            (
                header::CACHE_CONTROL,
                header::HeaderValue::from_static("no-cache"),
            ),
            // The operator's ingress buffers by default, which turns a follow
            // into bursts and looks like the feature is broken.
            (
                header::HeaderName::from_static("x-accel-buffering"),
                header::HeaderValue::from_static("no"),
            ),
        ],
        sse,
    )
        .into_response()
}

async fn logs_file(State(state): State<AppState>, Path(name): Path<String>) -> Response {
    let Some(path) = logsfs::resolve(&state.cfg.log_dir, &name) else {
        return error_response(StatusCode::NOT_FOUND, format!("no log file '{name}'"));
    };
    match tokio::fs::read(&path).await {
        Ok(bytes) => (
            [
                (header::CONTENT_TYPE, "text/plain; charset=utf-8"),
                (header::CONTENT_DISPOSITION, "attachment"),
            ],
            bytes,
        )
            .into_response(),
        Err(error) => error_response(StatusCode::INTERNAL_SERVER_ERROR, error),
    }
}

