const INDEX_HTML: &str = include_str!("../static/index.html");
const APP_JS: &str = include_str!("../static/app.js");
const STYLE_CSS: &str = include_str!("../static/style.css");
const APP_ICON: &[u8] = include_bytes!("../static/app_icon.png");

pub fn router(state: AppState) -> Router {
    let base_path = state.cfg.base_path.clone();
    let app = Router::new()
        .route("/", get(landing))
        .route("/ui", get(ui))
        .route("/app.js", get(app_js))
        .route("/style.css", get(style_css))
        .route("/app_icon.png", get(app_icon))
        .route("/api/controllers", get(controllers))
        .route("/api/config", get(config_defaults))
        .route("/api/health", get(health))
        .route("/api/ios", get(read_ios))
        .route("/api/ios/descriptions", get(io_descriptions))
        .route("/api/ios/create", post(ios_create))
        .route("/api/ios/delete", post(ios_delete))
        .route("/api/ios/{io}", put(write_io))
        .route("/api/ios/stream", get(ios_stream))
        .route("/api/run", get(run_status).post(run_start))
        .route("/api/stop", post(run_stop))
        .route("/api/status/stream", get(status_stream))
        .route("/api/logs", get(logs_list))
        .route("/api/logs", delete(logs_clear))
        .route("/api/logs/zip", get(logs_zip))
        .route("/api/logs/file/{name}", get(logs_file))
        .route("/api/logs/view/{name}", get(logs_view))
        .route("/api/logs/stream/{name}", get(logs_stream))
        .with_state(state);

    // The app may be reached both at "/" (locally, or if the ingress strips
    // the prefix) and under BASE_PATH (if it does not) — serve both. The
    // frontend only uses relative URLs, so either works.
    if base_path.len() > 1 {
        Router::new().nest(&base_path, app.clone()).merge(app)
    } else {
        app
    }
}

async fn landing(State(state): State<AppState>) -> Html<String> {
    // Absolute, BASE_PATH-prefixed links: the homescreen opens the app at
    // `{basePath}` WITHOUT a trailing slash, so a relative "ui" would resolve
    // against the parent segment (/cell/ui) and 404.
    let base = &state.cfg.base_path;
    Html(format!(
        "<!doctype html><title>audi-arg3-rust</title>\
         <p><a href=\"{base}/ui\">operator UI</a> · <a href=\"{base}/api/health\">health</a></p>"
    ))
}

