async fn logs_zip(State(state): State<AppState>) -> Response {
    let dir = state.cfg.log_dir.clone();
    match tokio::task::spawn_blocking(move || logsfs::zip_all(&dir)).await {
        Ok(Ok(bytes)) => (
            [
                (header::CONTENT_TYPE, "application/zip"),
                (
                    header::CONTENT_DISPOSITION,
                    "attachment; filename=\"arg3-rust-logs.zip\"",
                ),
            ],
            bytes,
        )
            .into_response(),
        Ok(Err(error)) => error_response(StatusCode::INTERNAL_SERVER_ERROR, error),
        Err(error) => error_response(StatusCode::INTERNAL_SERVER_ERROR, error),
    }
}

/// Parse `?offset=&limit=` by hand rather than through `Query`, whose
/// rejection is plain text — every error this app returns is
/// `{"detail": "<string>"}`, and the three Python siblings must match.

//! Controller and motion group discovery over the plain API. Mirrors the
//! Python api app's `discovery.py`.

use anyhow::{Context, Result};
use nova_client::types as t;

use crate::nova::Nova;

/// What the robots grid needs to know about one controller: its configured
/// TCPs (from the arm's motion group description — works for physical and
/// virtual controllers) and which one is active (from the state; selected on
/// the robot panel, read-only through the API).
#[derive(serde::Serialize)]
pub struct ControllerInfo {
    pub name: String,
    pub tcps: Vec<String>,
    pub active_tcp: Option<String>,
}

/// Controller info for the whole cell, fetched concurrently. A controller
/// whose description/state cannot be read still appears (empty `tcps`) so the
/// grid never loses robots.
pub async fn controller_infos(nova: &Nova) -> Result<Vec<ControllerInfo>> {
    let names = list_controllers(nova).await?;
    let fetches = names.into_iter().map(|name| async move {
        let motion_group = arm_motion_group(&name);
        let tcps: Result<Vec<String>> = async {
            let description = nova
                .raw
                .get_motion_group_description()
                .cell(&nova.cell)
                .controller(&name)
                .motion_group(&motion_group)
                .send()
                .await?
                .into_inner();
            let mut tcps: Vec<String> = description.tcps.keys().cloned().collect();
            tcps.sort();
            Ok(tcps)
        }
        .await;
        let active_tcp = match nova
            .raw
            .get_current_motion_group_state()
            .cell(&nova.cell)
            .controller(&name)
            .motion_group(&motion_group)
            .send()
            .await
        {
            Ok(state) => state.into_inner().tcp,
            Err(error) => {
                tracing::warn!(controller = %name, %error, "could not read active TCP");
                None
            }
        };
        let tcps = tcps.unwrap_or_else(|error| {
            tracing::warn!(controller = %name, error = format!("{error:#}"), "could not list TCPs");
            Vec::new()
        });
        ControllerInfo {
            name,
            tcps,
            active_tcp,
        }
    });
    Ok(futures_util::future::join_all(fetches).await)
}

/// Return the names of all controllers in the cell, sorted.
pub async fn list_controllers(nova: &Nova) -> Result<Vec<String>> {
    let names = nova
        .client
        .cell(&nova.cell)
        .controllers()
        .list()
        .await
        .context("list_robot_controllers")?;
    let mut names = names.0;
    names.sort();
    Ok(names)
}

async fn connected_motion_groups(nova: &Nova, controller: &str) -> Result<Vec<String>> {
    let description = nova
        .raw
        .get_controller_description()
        .cell(&nova.cell)
        .controller(controller)
        .send()
        .await
        .with_context(|| format!("{controller}: get_controller_description"))?
        .into_inner();
    Ok(description.connected_motion_groups)
}

/// Check whether `1@<controller>` exists and is a single prismatic joint —
/// the linear-axis rule shared with both Python apps. Any failure is reported
/// as "no axis" so an unreachable or odd controller cannot stop the app.
pub async fn has_linear_axis(nova: &Nova, controller: &str) -> bool {
    let axis_id = axis_motion_group(controller);
    let result: Result<bool> = async {
        if !connected_motion_groups(nova, controller)
            .await?
            .contains(&axis_id)
        {
            return Ok(false);
        }
        let description = nova
            .raw
            .get_motion_group_description()
            .cell(&nova.cell)
            .controller(controller)
            .motion_group(&axis_id)
            .send()
            .await?
            .into_inner();
        Ok(description.dh_parameters.len() == 1
            && description.dh_parameters[0].type_ == Some(t::JointTypeEnum::PrismaticJoint))
    }
    .await;
    match result {
        Ok(has_axis) => has_axis,
        Err(error) => {
            tracing::debug!(controller, %error, "could not inspect motion groups");
            false
        }
    }
}

/// The id of the robot arm motion group of a controller.
pub fn arm_motion_group(controller: &str) -> String {
    format!("0@{controller}")
}

/// The id of the linear axis motion group of a controller.
pub fn axis_motion_group(controller: &str) -> String {
    format!("1@{controller}")
}
