    pub tcp: String,
    pub step_rate_ms: i32,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Transport {
    Inline,
    Cached,
}

impl Transport {
    pub fn parse(s: &str) -> Option<Self> {
        match s {
            "inline" => Some(Self::Inline),
            "cached" => Some(Self::Cached),
            _ => None,
        }
