    pub fn name(self) -> &'static str {
        match self {
            Self::Inline => "inline",
            Self::Cached => "cached",
        }
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum StreamMode {
    Reopen,
    Persistent,
}

impl StreamMode {
    pub fn parse(s: &str) -> Option<Self> {
        match s {
            "reopen" => Some(Self::Reopen),
            "persistent" => Some(Self::Persistent),
            _ => None,
        }
    }
    pub fn name(self) -> &'static str {
