/// Same payload precedence as `../rust` (payload named like the TCP -> active
/// payload -> the only one). The planner uses it for dynamics; see there.
fn resolve_payload<'a>(
    description: &'a t::MotionGroupDescription,
    tcp: &str,
    active_payload: Option<&str>,
) -> Option<&'a t::Payload> {
    let payloads = &description.payloads;
    if let Some(p) = payloads.get(tcp) {
        return Some(p);
    }
    if let Some(active) = active_payload {
        if let Some(p) = payloads.get(active) {
            return Some(p);
        }
    }
    if payloads.len() == 1 {
        return payloads.values().next();
    }
    None
}

fn build_setup(
    description: &t::MotionGroupDescription,
    tcp: &str,
    state: &t::MotionGroupState,
    log: &RobotLog,
) -> t::MotionGroupSetup {
    let motion_group = &state.motion_group;
    let tcp_offset = description.tcps.get(tcp).map(|o| o.pose.clone());
    let payload = resolve_payload(description, tcp, state.payload.as_deref());
    match payload {
        None => log.warn(&format!(
            "{motion_group}: no payload resolved for TCP '{tcp}' (registered: {:?}) -- planning \
             as an UNLOADED robot",
            description.payloads.keys().collect::<Vec<_>>()
        )),
        Some(p) => log.info(&format!(
            "{motion_group}: planning with payload '{}' ({} kg)",
            p.name, p.payload
        )),
    }
    t::MotionGroupSetup {
        collision_setups: None,
        cycle_time: description.cycle_time.unwrap_or(8),
        global_limits: description.operation_limits.auto_limits.clone(),
        motion_group_model: description.motion_group_model.clone(),
        mounting: description.mounting.clone(),
        payload: payload.cloned(),
        tcp_offset,
    }
}

fn joint_ptp(target: &[f64], limits: Limits) -> t::MotionCommand {
    t::MotionCommand {
        blending: None,
        limits_override: Some(t::LimitsOverride {
            tcp_velocity_limit: Some(limits.velocity),
            tcp_acceleration_limit: Some(limits.acceleration),
            tcp_jerk_limit: Some(limits.jerk),
            joint_acceleration_limits: vec![],
            joint_jerk_limits: vec![],
            joint_velocity_limits: vec![],
            tcp_orientation_acceleration_limit: None,
            tcp_orientation_jerk_limit: None,
            tcp_orientation_velocity_limit: None,
        }),
        path: t::MotionCommandPath::JointPtp(t::PathJointPtp {
            path_definition_name: t::PathJointPtpPathDefinitionName::PathJointPtp,
            target_joint_position: t::DoubleArray(target.to_vec()),
        }),
    }
}

/// Resolve the TCP to plan with: UI pick -> the controller's active TCP ->
/// the env default; it must be configured on the controller.
pub fn resolve_tcp(
    description: &t::MotionGroupDescription,
    state: &t::MotionGroupState,
    requested: Option<&str>,
    fallback: &str,
) -> Result<String> {
    let tcp = requested
        .map(str::to_string)
        .or_else(|| state.tcp.clone())
        .unwrap_or_else(|| fallback.to_string());
    if !description.tcps.contains_key(&tcp) {
        let mut available: Vec<_> = description.tcps.keys().cloned().collect();
        available.sort();
        bail!(
            "{}: TCP '{tcp}' is not configured on this controller (available: {available:?}, \
             active: {:?})",
            state.motion_group,
            state.tcp
        );
    }
    Ok(tcp)
}

/// Plan joint 0 out by `delta_rad` and back, from `home` (two joint PTPs), so
/// the same trajectory can be executed again and again.
#[allow(clippy::too_many_arguments)]
pub async fn plan_out_and_back(
    nova: &Nova,
    controller: &str,
    motion_group: &str,
    description: &t::MotionGroupDescription,
    tcp: &str,
    home: &[f64],
    delta_rad: f64,
    limits: Limits,
    log: &RobotLog,
) -> Result<Planned> {
    let started = Instant::now();
    let state = current_state(nova, controller, motion_group).await?;
    let setup = build_setup(description, tcp, &state, log);
    let mut target = home.to_vec();
    target[0] += delta_rad;
    let commands = vec![joint_ptp(&target, limits), joint_ptp(home, limits)];
    let response = nova
        .raw
        .plan_trajectory()
        .cell(&nova.cell)
        .body(t::PlanTrajectoryRequest {
            motion_commands: commands,
            motion_group_setup: setup,
            singularity_handling: None,
            start_joint_position: t::DoubleArray(home.to_vec()),
        })
        .send()
        .await
        .with_context(|| format!("{motion_group}: plan_trajectory"))?
        .into_inner();
    let trajectory = match response.response {
        t::PlanTrajectoryResponseResponse::JointTrajectory(trajectory) => trajectory,
        t::PlanTrajectoryResponseResponse::PlanTrajectoryFailedResponse(failed) => bail!(
            "{motion_group}: planning failed at location {:?}: {:?}",
            failed.error_location_on_trajectory.0,
            failed.error_feedback
        ),
    };
    log.info(&format!(
        "{motion_group}: planned with tcp '{tcp}' in {:.3}s ({} samples, {:.3}s, end location {})",
        started.elapsed().as_secs_f64(),
        trajectory.joint_positions.len(),
        trajectory.times.last().copied().unwrap_or(0.0),
        trajectory.locations.last().map_or(0.0, |l| l.0),
    ));
    Ok(Planned {
        trajectory,
        tcp: tcp.to_string(),
        step_rate_ms: description.cycle_time.unwrap_or(8),
    })
}

pub fn duration_s(trajectory: &t::JointTrajectory) -> f64 {
    trajectory.times.last().copied().unwrap_or(0.0)
}

pub fn end_location(trajectory: &t::JointTrajectory) -> Option<f64> {
    trajectory.locations.last().map(|l| l.0)
}

/// The `response_rate` to request: 0 means the controller's step rate, asked
/// for by omitting the parameter (same as every sibling).
pub fn wire_rate(rate_ms: i32) -> Option<i32> {
    (rate_ms > 0).then_some(rate_ms)
}

fn initialize_error(ack: &t::InitializeMovementResponse) -> Option<String> {
    if let Some(error) = &ack.add_trajectory_error {
        return Some(
            error
                .message
                .clone()
                .unwrap_or_else(|| format!("{error:?}")),
        );
    }
    ack.message.clone().filter(|m| !m.is_empty())
}

/// Where the state frames of one execution come from.
pub enum Frames<'a> {
    /// `stream=persistent`: the run's one stream, opened before the loop.
    Shared(&'a mut StateStream),
    /// `stream=reopen`: opened inside `execute`, dropped at its end.
    Own(Option<StateStream>),
}

pub struct ExecuteParams<'a> {
    pub nova: &'a Nova,
    pub controller: &'a str,
    pub motion_group: &'a str,
    pub planned: &'a Planned,
    pub transport: Transport,
    pub response_rate: Option<i32>,
    pub frames: Frames<'a>,
    pub timeout: Duration,
    pub cancel: &'a CancellationToken,
    pub log: &'a RobotLog,
    pub timing: &'a mut CycleTiming,
    pub frames_file: Option<&'a crate::robot::FramesFile>,
}

/// Execute the planned trajectory once, stamping every step on `timing`.
pub async fn execute(p: ExecuteParams<'_>) -> Result<()> {
    let ExecuteParams {
        nova,
        controller,
        motion_group,
        planned,
        transport,
        response_rate,
        mut frames,
        timeout,
        cancel,
        log,
        timing,
        frames_file,
    } = p;
    timing.mark("execute_call");
    let cell = nova.client.cell(&nova.cell);

    // 1. The trajectory: cached (add_trajectory, then its id) or inline.
    let trajectory_ref = match transport {
        Transport::Cached => {
            let response = nova
                .raw
                .add_trajectory()
                .cell(&nova.cell)
                .controller(controller)
                .body(t::AddTrajectoryRequest {
                    motion_group: motion_group.to_string(),
                    tcp: Some(planned.tcp.clone()),
                    trajectory: planned.trajectory.clone(),
                })
                .send()
                .await
                .with_context(|| format!("{motion_group}: add_trajectory"))?
                .into_inner();
            timing.mark("add_trajectory_done");
            if let Some(error) = response.error {
                bail!("{motion_group}: add_trajectory rejected: {error:?}");
            }
            let id = response
                .trajectory
                .ok_or_else(|| anyhow!("{motion_group}: add_trajectory returned no id"))?;
            timing.motion_id = Some(id.clone());
            t::InitializeMovementRequestTrajectory::Id(t::TrajectoryId {
                id,
                message_type: t::TrajectoryIdMessageType::TrajectoryId,
            })
        }
        Transport::Inline => t::InitializeMovementRequestTrajectory::Data(t::TrajectoryData {
            data: planned.trajectory.clone(),
            message_type: t::TrajectoryDataMessageType::TrajectoryData,
            motion_group: Some(motion_group.to_string()),
            tcp: Some(planned.tcp.clone()),
        }),
    };

    // 2. The state stream: the run's shared one, or a fresh socket.
    let mut first_frame_pending = false;
    if let Frames::Own(slot) = &mut frames {
        timing.mark("stream_open");
        timing.socket_opens += 1;
        first_frame_pending = true;
        let stream = cell
            .motion_groups(controller)
            .state_stream(motion_group, response_rate, None)
            .await
            .with_context(|| format!("{motion_group}: opening state stream"))?;
        *slot = Some(stream);
    }
    let states: &mut StateStream = match &mut frames {
        Frames::Shared(stream) => stream,
        Frames::Own(slot) => slot.as_mut().expect("opened above"),
    };

    // 3. The execution websocket and the initialize handshake.
    let execution = cell
        .trajectory_execution()
        .execute_trajectory(controller)
        .await
        .with_context(|| format!("{motion_group}: opening execution websocket"))?;
    let (mut requests, mut responses) = execution.split();
    timing.mark("ws_init_sent");
    requests
        .send(&t::ExecuteTrajectoryRequest::InitializeMovementRequest(
            t::InitializeMovementRequest {
                message_type: t::InitializeMovementRequestMessageType::InitializeMovementRequest,
                trajectory: trajectory_ref,
                ignore_controller_limits: false,
                initial_location: Some(t::Location(0.0)),
                response_coordinate_system: None,
            },
        ))
        .await
        .with_context(|| format!("{motion_group}: sending InitializeMovementRequest"))?;

    loop {
        let ack = tokio::select! {
            response = responses.next() => response,
            _ = cancel.cancelled() => bail!("{motion_group}: cancelled"),
            _ = tokio::time::sleep(timeout) => {
                bail!("{motion_group}: no initialize acknowledgement within {timeout:?}")
            }
        };
        match ack {
            Some(Ok(t::ExecuteTrajectoryResponse::InitializeMovementResponse(ack))) => {
                timing.mark("ws_init_response");
                if let Some(error) = initialize_error(&ack) {
                    bail!("{motion_group}: initialize rejected: {error}");
                }
                break;
            }
            Some(Ok(t::ExecuteTrajectoryResponse::MovementErrorResponse(error))) => {
                bail!(
                    "{motion_group}: movement error during initialize: {}",
                    error.message
                )
            }
            Some(Ok(_)) => continue,
            Some(Err(error)) => {
                bail!("{motion_group}: execution websocket error during initialize: {error}")
            }
            None => bail!("{motion_group}: execution websocket closed during initialize"),
        }
    }

    // 4. Start, then read completion off the state stream.
    timing.mark("ws_start_sent");
    requests
        .send(&t::ExecuteTrajectoryRequest::StartMovementRequest(
            t::StartMovementRequest {
                message_type: t::StartMovementRequestMessageType::StartMovementRequest,
                direction: None,
                target_location: None,
                set_outputs: vec![],
                start_on_io: None,
                pause_on_io: None,
            },
        ))
        .await
        .with_context(|| format!("{motion_group}: sending StartMovementRequest"))?;

    let deadline = tokio::time::sleep(timeout);
    tokio::pin!(deadline);
    let mut fsm = ExecutionFsm::new();
    let mut execution_open = true;
    loop {
        tokio::select! {
            state = states.next() => {
                let state = match state {
                    Some(Ok(state)) => state,
                    Some(Err(error)) => {
                        log.warn(&format!("{motion_group}: state stream error frame: {error}"));
                        continue;
                    }
                    None => bail!(
                        "{motion_group}: state stream ended after {} frame(s) without \
                         reporting completion",
                        timing.frames
                    ),
                };
                if first_frame_pending {
                    timing.stream_first_frame = Some(Instant::now());
                    first_frame_pending = false;
                }
                let facts = FrameFacts::from_state(&state);
                timing.on_frame(&facts);
                if let Some(file) = frames_file {
                    file.write(timing.index, &facts);
                }
                // Only frames of this execution (or without an execute block,
                // the legacy completion path) reach the FSM: the previous
                // trajectory's re-published END must not conclude this one.
                let own = facts.trajectory.is_none()
                    || facts.trajectory == timing.motion_id;
                if !own {
                    continue;
                }
                if facts.kind == Some("END_OF_TRAJECTORY") {
                    timing.final_location = facts.location;
                }
                match fsm.process(ExecuteSignal::from_state(&state), state.standstill) {
                    None => {}
                    Some(Outcome::Completed) | Some(Outcome::CompletedLegacy) => {
                        timing.mark("op_done");
                        break;
                    }
                    Some(Outcome::PausedAfterMotion) => {
                        bail!("{motion_group}: motion was paused at standstill after motion");
                    }
                }
            }
            response = responses.next(), if execution_open => {
                match response {
                    Some(Ok(t::ExecuteTrajectoryResponse::StartMovementResponse(_))) => {
                        timing.mark("ws_start_response");
                    }
                    Some(Ok(t::ExecuteTrajectoryResponse::MovementErrorResponse(error))) => {
                        bail!("{motion_group}: movement error: {}", error.message)
                    }
                    Some(Ok(_)) => {}
                    Some(Err(error)) => {
                        log.warn(&format!(
                            "{motion_group}: execution websocket error, still watching the \
                             state stream: {error}"
                        ));
                        execution_open = false;
                    }
                    None => execution_open = false,
                }
            }
            _ = cancel.cancelled() => bail!("{motion_group}: cancelled"),
            _ = &mut deadline => {
                bail!(
                    "{motion_group}: no completion within {:.0}s ({} state frame(s) seen)",
                    timeout.as_secs_f64(),
                    timing.frames
                )
            }
        }
    }

    // 5. Teardown: close the execution socket; a per-execution state socket
    //    is dropped here (the client has no close handshake for it).
    let _ = requests.close().await;
    drop(requests);
    drop(responses);
    if let Frames::Own(slot) = &mut frames {
        *slot = None;
        timing.stream_closed = Some(Instant::now());
    }
    timing.mark("execute_return");
    Ok(())
}
