//! The per-robot worker: wait for the start IO once -> control mode -> read
//! home -> plan (and store, in `store` mode) -> loop: poll the stop IO, fetch
//! the trajectory as `mode` says, execute with every step stamped, log one
//! readable line and one `PHASES {json}` line, every `summary_every` cycles a
//! `SUMMARY`. The Rust twin of `../succession/audi_arg3_succession/programs.py`
//! on the run model of `../rust/src/robot.rs` (one tokio task per robot).
//!
//! No retries around motions: a failed cycle is logged with its stamps and
//! ends the run.

use std::fs::{File, OpenOptions};
use std::io::Write;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

use anyhow::{bail, Context, Result};
use nova_client::types as t;
use serde_json::json;
use tokio_util::sync::CancellationToken;

use crate::busio::{self, IoHub};
use crate::config::Config;
use crate::discovery;
use crate::motion::{self, Frames, Limits, Planned, StateStream, StreamMode, Transport};
use crate::nova::Nova;
use crate::robotlog::RobotLog;
use crate::runner::{IoGate, Registry, RunOptions};
use crate::timing::{CycleTiming, FrameFacts, Stats};

pub struct RobotCtx {
    pub nova: Nova,
    pub cfg: Config,
    pub hub: Arc<IoHub>,
    pub registry: Arc<Registry>,
    pub controller: String,
    pub tcp: Option<String>,
    pub gate: IoGate,
    pub options: RunOptions,
    pub cancel: CancellationToken,
}

const STORE_KEY_PREFIX: &str = "arg3-succession-rust/";

/// Optional per-frame JSONL beside the log, capped at `max_bytes`.
pub struct FramesFile {
    inner: Mutex<FramesInner>,
}

struct FramesInner {
    file: Option<File>,
    written: u64,
    max_bytes: u64,
    capped: bool,
}

impl FramesFile {
    pub fn open(dir: &str, controller: &str, max_bytes: u64) -> Self {
        let path = std::path::PathBuf::from(dir).join(format!("{controller}-frames.log"));
        let _ = std::fs::create_dir_all(dir);
        let file = OpenOptions::new().create(true).append(true).open(&path).ok();
        let written = file
            .as_ref()
            .and_then(|f| f.metadata().ok())
            .map_or(0, |m| m.len());
        Self {
            inner: Mutex::new(FramesInner {
                file,
                written,
                max_bytes,
                capped: false,
            }),
        }
    }

    pub fn write(&self, cycle: u64, facts: &FrameFacts) {
        let mut inner = self.inner.lock().unwrap_or_else(|p| p.into_inner());
        if inner.capped {
            return;
        }
        let line = json!({
            "t": chrono::Utc::now().timestamp_micros() as f64 / 1e6,
            "i": cycle,
            "ts": facts.timestamp,
            "seq": facts.sequence,
            "standstill": facts.standstill,
            "kind": facts.kind,
            "location": facts.location,
            "trajectory": facts.trajectory,
            "j0": facts.joint0,
        })
        .to_string()
            + "\n";
        if inner.written + line.len() as u64 > inner.max_bytes {
            inner.capped = true;
            return;
        }
        if let Some(file) = inner.file.as_mut() {
            if file.write_all(line.as_bytes()).is_ok() {
                inner.written += line.len() as u64;
            }
        }
    }
}

async fn should_stop(nova: &Nova, gate: &IoGate, log: &RobotLog) -> bool {
    let stop_io = &gate.stop_io;
    match busio::read_ios(nova, std::slice::from_ref(stop_io)).await {
        Ok(values) => values.get(stop_io) == Some(&json!(gate.stop_io_value)),
        Err(error) => {
            log.warn(&format!("could not read stop IO '{stop_io}': {error:#}"));
            false
        }
    }
}

/// Wait once for the start IO. Returns false when it cannot be read at all
/// (no bus-IO service, no such signal): the run then goes ahead ungated and
/// the stop IO is not polled either -- the same choice as the Python twin, so
/// the two stay comparable on a cell without the gate signals. (`../rust`
/// fails loudly instead; its gate is a safety feature on the production cell.)
async fn wait_for_start(ctx: &RobotCtx, log: &RobotLog) -> bool {
    let gate = &ctx.gate;
    match busio::read_ios(&ctx.nova, std::slice::from_ref(&gate.wait_io)).await {
        Ok(_) => {}
        Err(error) => {
            log.warn(&format!(
                "{}: could not read start IO '{}' ({error:#}); running ungated, stop IO not polled",
                ctx.controller, gate.wait_io
            ));
            return false;
        }
    }
    if let Err(error) = busio::wait_for_io(
        &ctx.hub,
        &ctx.nova,
        &gate.wait_io,
        gate.wait_io_value,
        &ctx.cancel,
        log,
    )
    .await
    {
        log.warn(&format!(
            "{}: waiting for start IO '{}' failed ({error:#}); running ungated",
            ctx.controller, gate.wait_io
        ));
        return false;
    }
    true
}

pub async fn run(ctx: RobotCtx) {
    let controller = ctx.controller.clone();
    let log = RobotLog::open(
        &ctx.cfg.log_dir,
        &controller,
        ctx.cfg.log_max_bytes,
        ctx.cfg.log_backup_count,
    );
    match run_inner(&ctx, &log).await {
        Ok(cycles) => {
            log.info(&format!("{controller}: finished after {cycles} cycle(s)"));
            ctx.registry.update(&controller, |s| {
                s.running = false;
                s.state = "finished".to_string();
                s.finished_at = Some(chrono::Utc::now());
            });
        }
        Err(error) => {
            if ctx.cancel.is_cancelled() {
                log.info(&format!("{controller}: stopped ({error:#})"));
                ctx.registry.update(&controller, |s| {
                    s.running = false;
                    s.state = "stopped".to_string();
                    s.finished_at = Some(chrono::Utc::now());
                });
            } else {
                log.error(&format!("{controller}: run failed: {error:#}"));
                tracing::error!(controller, error = format!("{error:#}"), "robot run failed");
                ctx.registry.update(&controller, |s| {
                    s.running = false;
                    s.state = "failed".to_string();
                    s.errors += 1;
                    s.last_error = Some(format!("{error:#}"));
                    s.finished_at = Some(chrono::Utc::now());
                });
            }
        }
    }
}

async fn run_inner(ctx: &RobotCtx, log: &RobotLog) -> Result<u64> {
    let RobotCtx {
        nova,
        cfg,
        registry,
        controller,
        tcp,
        gate,
        options,
        cancel,
        ..
    } = ctx;
    let motion_group = discovery::arm_motion_group(controller);
    let transport = options.transport;
    let stream_mode = options.stream;
    let sign = if options.direction == "negative" { -1.0 } else { 1.0 };
    let delta_rad = sign * options.degrees.to_radians();
    let limits = Limits {
        velocity: options.velocity,
        acceleration: options.acceleration,
        jerk: options.jerk,
    };

    log.info(&format!(
        "{controller}: successive-execution timing -- mode={} ({}); stream={} ({}); \
         trajectory={} ({}); cycles={}; wait IO '{}'=={} once before the loop, stop IO '{}'=={} \
         ends it",
        options.mode,
        mode_help(&options.mode),
        stream_mode.name(),
        stream_help(stream_mode),
        transport.name(),
        transport_help(transport),
        if options.cycles == 0 { "until stop".to_string() } else { options.cycles.to_string() },
        gate.wait_io,
        gate.wait_io_value,
        gate.stop_io,
        gate.stop_io_value,
    ));
    log.info(&format!(
        "{controller}: tcp={}, joint 0 {}{} deg and back, state_rate={}, gap_ms={}, \
         summary_every={}, record_frames={}, motion_timeout={:.0}s, limits v={:.0} mm/s \
         a={:.0} mm/s2 j={:.0} mm/s3, max_motion_s={}",
        tcp.as_deref().unwrap_or("<active>"),
        if sign > 0.0 { "+" } else { "-" },
        options.degrees,
        if options.state_rate_ms > 0 {
            format!("{} ms", options.state_rate_ms)
        } else {
            "controller step rate".to_string()
        },
        options.gap_ms,
        options.summary_every,
        options.record_frames,
        cfg.motion_timeout.as_secs_f64(),
        limits.velocity,
        limits.acceleration,
        limits.jerk,
        if options.max_motion_s > 0.0 {
            format!("{:.1}", options.max_motion_s)
        } else {
            "unchecked".to_string()
        },
    ));
    log.info(&format!(
        "{controller}: nova-rust-client (vendored, {}), audi-arg3-succession-rust {}",
        include_str!("../vendor/nova-rust-client/.vendored-from").trim(),
        env!("CARGO_PKG_VERSION")
    ));

    registry.update(controller, |s| s.state = "waiting for start".to_string());
    let gated = wait_for_start(ctx, log).await;

    nova.raw
        .set_default_mode()
        .cell(&nova.cell)
        .controller(controller)
        .mode(t::SettableRobotSystemMode::ModeControl)
        .send()
        .await
        .map_err(|e| anyhow::anyhow!("{controller}: set_default_mode: {e}"))?;

    registry.update(controller, |s| s.state = "planning".to_string());
    let description = motion::get_description(nova, controller, &motion_group).await?;
    let state = motion::current_state(nova, controller, &motion_group).await?;
    let tcp = motion::resolve_tcp(&description, &state, tcp.as_deref(), &cfg.tcp)?;
    registry.update(controller, |s| s.tcp = Some(tcp.clone()));
    let home: Vec<f64> = state.joint_position.0.clone();
    log.info(&format!(
        "{controller}: home joints {:?}, joint 0 target {:.4} rad",
        home.iter().map(|v| (v * 1e4).round() / 1e4).collect::<Vec<_>>(),
        home[0] + delta_rad
    ));
    let plan = || {
        motion::plan_out_and_back(
            nova,
            controller,
            &motion_group,
            &description,
            &tcp,
            &home,
            delta_rad,
            limits,
            log,
        )
    };
    let mut planned: Planned = plan().await?;
    check_motion_length(&planned, options.max_motion_s, options.degrees, controller)?;
    let end_location = motion::end_location(&planned.trajectory);
    log.info(&format!(
        "{controller}: state stream rate {}",
        match motion::wire_rate(options.state_rate_ms) {
            Some(ms) => format!("{ms} ms (requested)"),
            None => format!(
                "controller step rate (~{} ms, response_rate omitted)",
                planned.step_rate_ms
            ),
        }
    ));

    let store_key = format!("{STORE_KEY_PREFIX}{controller}");
    if options.mode == "store" {
        let started = Instant::now();
        let bytes = serde_json::to_vec(&planned.trajectory)?;
        nova.client
            .cell(&nova.cell)
            .store()
            .put(&store_key, bytes, &[])
            .await
            .with_context(|| format!("{controller}: store put"))?;
        log.info(&format!(
            "{controller}: stored the trajectory under '{store_key}' in {:.3}s",
            started.elapsed().as_secs_f64()
        ));
    }

    // stream=persistent: one state socket for the whole run, opened here.
    let mut shared_stream: Option<StateStream> = None;
    if stream_mode == StreamMode::Persistent {
        let stream = nova
            .client
            .cell(&nova.cell)
            .motion_groups(controller)
            .state_stream(&motion_group, motion::wire_rate(options.state_rate_ms), None)
            .await
            .with_context(|| format!("{motion_group}: opening the persistent state stream"))?;
        shared_stream = Some(stream);
        log.info(&format!("{controller}: persistent state stream opened for the run"));
    }

    let frames_file = options
        .record_frames
        .then(|| FramesFile::open(&cfg.log_dir, controller, cfg.frames_max_bytes));
    let mut stats = Stats::default();
    let mut previous: Option<CycleTiming> = None;
    let mut cycle: u64 = 0;
    let mut motion_seconds_total = 0.0_f64;

    let outcome: Result<()> = async {
        while options.cycles == 0 || cycle < options.cycles {
            if cancel.is_cancelled() {
                bail!("cancelled");
            }
            let mut timing = CycleTiming::new(cycle + 1, end_location, home.first().copied());
            timing.previous_motion_id = previous.as_ref().and_then(|p| p.motion_id.clone());
            timing.mark("stop_poll_start");
            let stop = gated && should_stop(nova, gate, log).await;
            timing.mark("stop_poll_done");
            if stop {
                log.info(&format!(
                    "{controller}: stop IO '{}' is {}, exiting loop",
                    gate.stop_io, gate.stop_io_value
                ));
                break;
            }
            cycle += 1;
            registry.update(controller, |s| {
                s.cycle = cycle;
                s.state = "executing".to_string();
            });

            match options.mode.as_str() {
                "plan-each" => {
                    timing.mark("prepare_start");
                    planned = plan().await?;
                    timing.mark("prepare_done");
                }
                "store" => {
                    timing.mark("prepare_start");
                    let bytes = nova
                        .client
                        .cell(&nova.cell)
                        .store()
                        .get(&store_key)
                        .await
                        .with_context(|| format!("{controller}: store get"))?
                        .bytes()
                        .await
                        .with_context(|| format!("{controller}: store read"))?;
                    let trajectory: t::JointTrajectory = serde_json::from_slice(&bytes)
                        .with_context(|| format!("{controller}: stored trajectory"))?;
                    planned = Planned {
                        trajectory,
                        tcp: planned.tcp.clone(),
                        step_rate_ms: planned.step_rate_ms,
                    };
                    timing.mark("prepare_done");
                }
                _ => {}
            }

            timing.socket_open_at_call = Some(shared_stream.is_some());
            let started = Instant::now();
            let frames = match shared_stream.as_mut() {
                Some(stream) => Frames::Shared(stream),
                None => Frames::Own(None),
            };
            let result = motion::execute(motion::ExecuteParams {
                nova,
                controller,
                motion_group: &motion_group,
                planned: &planned,
                transport,
                response_rate: motion::wire_rate(options.state_rate_ms),
                frames,
                timeout: cfg.motion_timeout,
                cancel,
                log,
                timing: &mut timing,
                frames_file: frames_file.as_ref(),
            })
            .await;
            if let Err(error) = result {
                timing.error = Some(format!("{error:#}"));
                timing.finish(previous.as_ref());
                log.error(&format!(
                    "{controller}: cycle {cycle} FAILED: {error:#} | {} | PHASES {}",
                    timing.headline(),
                    timing.record()
                ));
                return Err(error);
            }
            timing.finish(previous.as_ref());
            let execute_s = started.elapsed().as_secs_f64();
            motion_seconds_total += execute_s;
            registry.update(controller, |s| {
                s.last_cycle_s = Some(execute_s);
                s.avg_motion_s = Some(motion_seconds_total / cycle as f64);
            });
            let anomalies = timing.anomalies();
            let line = format!(
                "{controller}: cycle {cycle} -- execute() {:.0} ms | {} | frames={} own={} socket_opens={}{}",
                timing.phase("execute").unwrap_or(-1.0),
                timing.headline(),
                timing.frames,
                timing.own_frames,
                timing.socket_opens,
                if anomalies.is_empty() {
                    String::new()
                } else {
                    format!(" | ANOMALY {}", anomalies.join("; "))
                }
            );
            if anomalies.is_empty() {
                log.info(&line);
            } else {
                log.warn(&line);
            }
            log.info(&format!("{controller}: PHASES {}", timing.record()));

            if let Some(mut prev) = previous.take() {
                prev.finish_late(timing.marks.get("execute_call").copied());
                stats.add(&prev);
            }
            previous = Some(timing);

            if options.summary_every > 0 && cycle % options.summary_every == 0 {
                log.info(&format!(
                    "{controller}: SUMMARY after {cycle} cycles (ms)\n{}",
                    stats.table()
                ));
            }
            if options.gap_ms > 0 {
                tokio::select! {
                    _ = tokio::time::sleep(Duration::from_millis(options.gap_ms)) => {}
                    _ = cancel.cancelled() => bail!("cancelled"),
                }
            }
        }
        Ok(())
    }
    .await;

    if let Some(mut prev) = previous.take() {
        prev.finish_late(None);
        stats.add(&prev);
    }
    drop(shared_stream);
    log.info(&format!(
        "{controller}: finished after {cycle} cycles -- SUMMARY (ms)\n{}\n{controller}: SUMMARY_JSON {}",
        stats.table(),
        stats.summary()
    ));
    outcome.map(|()| cycle)
}

/// Refuse a trajectory longer than `max_motion_s` before anything moves.
fn check_motion_length(planned: &Planned, max_motion_s: f64, degrees: f64, controller: &str) -> Result<()> {
    let duration = motion::duration_s(&planned.trajectory);
    if max_motion_s <= 0.0 || duration <= max_motion_s {
        return Ok(());
    }
    bail!(
        "{controller}: the planned out-and-back move takes {duration:.2}s, more than \
         max_motion_s={max_motion_s:.1}s -- pick fewer degrees than {degrees} or raise the \
         velocity / acceleration / jerk limits, or set max_motion_s=0 to run anyway"
    )
}

pub fn mode_help(mode: &str) -> &'static str {
    match mode {
        "plan-each" => "plan the trajectory afresh before every execution",
        "plan-once" => "plan once before the loop and execute the same JointTrajectory every cycle",
        "store" => "plan once, write the trajectory to the store-object service, read it back before every execution",
        _ => "?",
    }
}

pub fn stream_help(stream: StreamMode) -> &'static str {
    match stream {
        StreamMode::Reopen => "every execution opens the motion-group state websocket and closes it",
        StreamMode::Persistent => "one state websocket is opened before the loop and read by every execution",
    }
}

pub fn transport_help(transport: Transport) -> &'static str {
    match transport {
        Transport::Inline => "the JointTrajectory is sent inline in InitializeMovementRequest (no add_trajectory call)",
        Transport::Cached => "add_trajectory first, then InitializeMovementRequest with the id (what the Python SDK does)",
    }
}
