/// One option as the UI posted it: a string for selects and numbers, a bool
/// for checkboxes, or nothing.
fn option_str(options: &serde_json::Map<String, serde_json::Value>, name: &str) -> Option<String> {
    match options.get(name) {
        Some(serde_json::Value::String(text)) if !text.trim().is_empty() => Some(text.trim().to_string()),
        Some(serde_json::Value::Number(number)) => Some(number.to_string()),
        Some(serde_json::Value::Bool(flag)) => Some(flag.to_string()),
        _ => None,
    }
}

fn option_number<T: std::str::FromStr + PartialOrd + Copy + std::fmt::Display>(
    options: &serde_json::Map<String, serde_json::Value>,
    name: &str,
    default: T,
    lo: T,
    hi: T,
) -> Result<T, String> {
    let Some(text) = option_str(options, name) else {
        return Ok(default);
    };
    match text.parse::<T>() {
        Ok(value) if value >= lo && value <= hi => Ok(value),
        _ => Err(format!("{name} must be a number between {lo} and {hi}, got {text:?}")),
    }
}

fn option_choice(
    options: &serde_json::Map<String, serde_json::Value>,
    name: &str,
    default: &str,
    choices: &[&str],
) -> Result<String, String> {
    let value = option_str(options, name).unwrap_or_else(|| default.to_string());
    if choices.contains(&value.as_str()) {
        Ok(value)
    } else {
        Err(format!("{name} must be one of {choices:?}, got {value:?}"))
    }
}

/// Parse the UI's `options` object into `RunOptions`, every value checked.
fn run_options_from(
    options: &serde_json::Map<String, serde_json::Value>,
    cfg: &Config,
) -> Result<crate::runner::RunOptions, String> {
    let mode = option_choice(options, "mode", "plan-once", &["plan-each", "plan-once", "store"])?;
    let stream = option_choice(options, "stream", "reopen", &["reopen", "persistent"])?;
    let transport = option_choice(options, "transport", "cached", &["cached", "inline"])?;
    let degrees = option_number(options, "degrees", cfg.degrees, 0.0, 360.0)?;
    if !crate::config::DEGREE_PRESETS.contains(&degrees) {
        return Err(format!(
            "degrees must be one of {:?}, got {degrees}",
            crate::config::DEGREE_PRESETS
        ));
    }
    Ok(crate::runner::RunOptions {
        mode,
        stream: crate::motion::StreamMode::parse(&stream).expect("validated"),
        transport: crate::motion::Transport::parse(&transport).expect("validated"),
        cycles: option_number(options, "cycles", cfg.cycles, 0, 1_000_000)?,
        degrees,
        direction: option_choice(options, "direction", "positive", &["positive", "negative"])?,
        state_rate_ms: state_rate_from_options(options, cfg.state_response_rate_ms)?,
        gap_ms: option_number(options, "gap_ms", 0, 0, 600_000)?,
        summary_every: option_number(options, "summary_every", cfg.summary_every, 0, 100_000)?,
        record_frames: matches!(options.get("record_frames"), Some(serde_json::Value::Bool(true))),
        velocity: option_number(options, "velocity", cfg.velocity, 1.0, 10_000.0)?,
        acceleration: option_number(options, "acceleration", cfg.acceleration, 1.0, 100_000.0)?,
        jerk: option_number(options, "jerk", cfg.jerk, 1.0, 1_000_000.0)?,
        max_motion_s: option_number(options, "max_motion_s", cfg.max_motion_s, 0.0, 3600.0)?,
    })
}

